INSERT INTO `news` VALUES (1,'CÁN BỘ, NHÂN VIÊN VIỆT THẮNG THAM GIA CHƯƠNG TRÌNH NGHỈ MÁT HÈ 2026 TẠI QUY NHƠN',NULL,'can-bo-nhan-vien-viet-thang-tham-gia-chuong-trinh-nghi-mat-he-2026-tai-quy-nhon',NULL,'Nhằm tạo điều kiện để cán bộ, nhân viên nghỉ ngơi, tái tạo năng lượng sau thời gian làm việc, đồng thời tăng cường sự gắn kết giữa các thành viên, Công ty Cổ phần Thiết bị Công nghiệp và Chuyển giao Công nghệ Việt Thắng đã tổ chức chương trình nghỉ mát hè năm 2026 tại thành phố Quy Nhơn, tỉnh Bình Định trong tháng 8/2026.',NULL,'<h1>CÁN BỘ, NHÂN VIÊN VIỆT THẮNG THAM GIA CHƯƠNG TRÌNH NGHỈ MÁT HÈ 2026 TẠI QUY NHƠN</h1><p>Nhằm tạo điều kiện để cán bộ, nhân viên nghỉ ngơi, tái tạo năng lượng sau thời gian làm việc, đồng thời tăng cường sự gắn kết giữa các thành viên, Công ty Cổ phần Thiết bị Công nghiệp và Chuyển giao Công nghệ Việt Thắng đã tổ chức <strong>chương trình nghỉ mát hè năm 2026 tại thành phố Quy Nhơn, tỉnh Bình Định</strong> trong tháng 8/2026.<img src=\"http://127.0.0.1:8000/storage/news/GGtE8cDGmYZQXJNjzjQv9vHoc2qtr0rp2EH61jTm.jpg\" data-id=\"news/GGtE8cDGmYZQXJNjzjQv9vHoc2qtr0rp2EH61jTm.jpg\"></p><p>Chương trình là dịp để cán bộ, nhân viên Công ty cùng nhau tạm gác lại công việc thường nhật, tận hưởng không khí biển, khám phá cảnh quan và trải nghiệm những hoạt động tập thể ý nghĩa tại Quy Nhơn – một trong những điểm đến nổi bật của miền Trung.</p><h2>Gắn kết tập thể – Tái tạo năng lượng</h2><p>Trong khuôn khổ chuyến đi, cán bộ, nhân viên Việt Thắng đã có những khoảng thời gian thư giãn, vui chơi và tham quan cùng đồng nghiệp. Các hoạt động tập thể góp phần tạo nên không khí sôi nổi, gần gũi, giúp các thành viên có thêm cơ hội giao lưu và hiểu nhau hơn.</p><p>Bên cạnh những trải nghiệm tại biển Quy Nhơn, chương trình cũng mang đến nhiều khoảnh khắc đáng nhớ khi các thành viên cùng nhau tham gia các hoạt động chung, lưu giữ những hình ảnh đẹp và chia sẻ những kỷ niệm ngoài môi trường làm việc.</p><h2>Xây dựng văn hóa doanh nghiệp</h2><p><img src=\"http://127.0.0.1:8000/storage/news/AQVEz90OnDoQedO1iBwlPBA8jGGzQOomv3GOEllq.png\" data-id=\"news/AQVEz90OnDoQedO1iBwlPBA8jGGzQOomv3GOEllq.png\"></p><h2>Đối với Việt Thắng, con người luôn là một trong những yếu tố quan trọng tạo nên sự phát triển bền vững của Công ty. Bên cạnh việc xây dựng môi trường làm việc chuyên nghiệp, Công ty luôn chú trọng các hoạt động gắn kết tập thể và chăm lo đời sống tinh thần cho cán bộ, nhân viên.</h2><p>Chương trình nghỉ mát hè 2026 không chỉ là dịp để mọi người nghỉ ngơi, thư giãn mà còn góp phần củng cố tinh thần đoàn kết, tạo động lực để tập thể Việt Thắng tiếp tục đồng hành, phối hợp hiệu quả và hướng tới những mục tiêu mới trong thời gian tới.</p><p>Khép lại chuyến nghỉ mát tại Quy Nhơn, mỗi thành viên trở lại công việc với tinh thần sảng khoái, nguồn năng lượng mới và sự gắn kết hơn trong tập thể.</p><p><strong>Việt Thắng – Đoàn kết để phát triển, đồng hành để vươn xa.</strong></p>','<p></p>','news/01M1X8ZDC70E8RG2SAWYARD7YN.jpg','published','2026-09-06 23:33:05',1,'2026-09-06 23:30:33','2026-09-06 23:33:05',NULL);
/*!40000 ALTER TABLE `news` ENABLE KEYS */;
UNLOCK TABLES;

