INSERT INTO `products` VALUES (1,9,'Thiết bị phát hiện ma túy, chất nổ công nghệ phổ Raman','Handheld Raman Spectroscopy Drug & Explosives Detector','thiet-bi-phat-hien-ma-tuy-chat-no-cong-nghe-pho-raman','handheld-raman-spectroscopy-drug-explosives-detector',NULL,'Thiết bị được thiết kế cầm tay để đo quang phổ Raman, chuyên dùng nhận dạng nhanh các chất ở dạng bột và lỏng như chất nổ, ma túy, chất gây nghiện, chất độc hại và tác nhân chiến tranh hóa học nguy hiểm.','A handheld Raman spectroscopy device designed for the rapid identification of powder and liquid substances such as explosives, narcotics, controlled substances, hazardous chemicals and dangerous chemical warfare agents.','<p>Thiết bị được thiết kế cầm tay để đo quang phổ Raman, chuyên dùng nhận dạng nhanh các chất ở dạng bột và lỏng như chất nổ, ma túy, chất gây nghiện, chất độc hại và tác nhân chiến tranh hóa học nguy hiểm. Với khả năng loại bỏ nhiễu huỳnh quang và quy trình phân tích hoàn toàn tự động, thiết bị cho phép kiểm tra hiệu quả mà không cần phá hủy mẫu.</p>','<p>A handheld Raman spectroscopy device designed for the rapid identification of powder and liquid substances such as explosives, narcotics, controlled substances, hazardous chemicals and dangerous chemical warfare agents. With fluorescence-noise rejection and a fully automated analysis process, the device enables effective, non-destructive testing of the sample.</p>','published',0,0,NULL,NULL,'2026-08-21 00:18:18',NULL,1,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(2,9,'Thiết bị phát hiện chất nổ, chất độc, ma túy và các hóa chất nguy hiểm dạng hơi','Vapor-Phase Explosives, Narcotics & Hazardous Chemical Detector','thiet-bi-phat-hien-chat-no-chat-doc-ma-tuy-va-cac-hoa-chat-nguy-hiem-dang-hoi','vapor-phase-explosives-narcotics-hazardous-chemical-detector',NULL,'Thiết bị được thiết kế để phát hiện nhanh dấu vết của vật liệu nổ, ma túy, hóa chất nguy hiểm và tác nhân chiến tranh hóa học trong không khí, trên da, quần áo, sử dụng công nghệ phổ Ion hiện đại.','A device designed to rapidly detect trace vapors of explosives, narcotics, hazardous chemicals and chemical warfare agents in the air, on skin or on clothing, using modern Ion Mobility Spectrometry (IMS) technology.','<p>Thiết bị được thiết kế để phát hiện nhanh dấu vết của vật liệu nổ, ma túy, hóa chất nguy hiểm và tác nhân chiến tranh hóa học trong không khí, trên da, quần áo, sử dụng công nghệ phổ Ion hiện đại. Thời gian phát hiện nhanh, với khả năng nhận dạng chính xác các chất trong thư viện dữ liệu tích hợp sẵn, giúp nâng cao hiệu quả kiểm soát trong các tình huống khẩn cấp tại các điểm kiểm soát an ninh, hải quan và biên giới.</p>','<p>A device designed to rapidly detect trace vapors of explosives, narcotics, hazardous chemicals and chemical warfare agents in the air, on skin or on clothing, using modern Ion Mobility Spectrometry (IMS) technology. Fast detection time combined with accurate substance identification against a built-in reference library increases screening effectiveness in emergency situations at security checkpoints, customs and border crossings.</p>','published',0,1,NULL,NULL,'2026-08-21 00:18:18',NULL,1,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(3,9,'Máy dò nhanh chất độc, chất phóng xạ','Rapid Chemical & Radiation Detector','may-do-nhanh-chat-doc-chat-phong-xa','rapid-chemical-radiation-detector',NULL,'Thiết bị được thiết kế dạng cầm tay hai trong một, cho phép dò nhanh cả chất độc và chất phóng xạ, phù hợp với lực lượng cảnh sát cơ động, đặc nhiệm và quân đội.','A handheld, two-in-one device enabling rapid detection of both toxic chemicals and radioactive materials, suited to mobile police, special forces and military units.','<p>Thiết bị được thiết kế dạng cầm tay hai trong một, cho phép dò nhanh cả chất độc và chất phóng xạ, phù hợp với lực lượng cảnh sát cơ động, đặc nhiệm và quân đội. Thiết bị có khả năng phát hiện nhanh các chất độc nguy hiểm như hợp chất phốt pho hữu cơ (GD, GB, VX) và các hợp chất asen. Khi phát hiện vượt ngưỡng, thiết bị sẽ cảnh báo bằng âm thanh và hiển thị trực quan trên màn hình LED. Thời gian phát hiện nhanh giúp nâng cao hiệu quả phản ứng trong các tình huống khẩn cấp.</p>','<p>A handheld, two-in-one device enabling rapid detection of both toxic chemicals and radioactive materials, suited to mobile police, special forces and military units. The device can quickly detect dangerous toxic agents such as organophosphorus compounds (GD, GB, VX) and arsenic compounds. When a reading exceeds the threshold, the device issues an audible alert and a visual indication on its LED display. Fast detection speeds up response in emergency situations.</p>','published',0,2,NULL,NULL,'2026-08-21 00:18:18',NULL,1,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(4,9,'Thiết bị soi chiếu Xray cầm tay','Handheld X-ray Screening Device','thiet-bi-soi-chieu-xray-cam-tay','handheld-x-ray-screening-device',NULL,'Hệ thống soi chiếu X-ray cầm tay được trang bị bộ phát tia X và tấm thu nhỏ gọn, cho phép sử dụng cơ động để phát hiện vũ khí, hàng cấm ẩn giấu trong vali, túi xách, bao bì, bưu kiện hoặc bên trong phương tiện.','A handheld X-ray screening system fitted with a compact X-ray source and detector panel, enabling mobile inspection to detect weapons and prohibited items concealed in luggage, bags, packages, parcels or inside vehicles.','<p>Hệ thống soi chiếu X-ray cầm tay được trang bị bộ phát tia X và tấm thu nhỏ gọn, cho phép sử dụng cơ động để phát hiện vũ khí, hàng cấm ẩn giấu trong vali, túi xách, bao bì, bưu kiện hoặc bên trong phương tiện. Thiết bị cho phép kiểm tra không phá hủy, đặc biệt hiệu quả tại các vị trí khó tiếp cận như lốp xe, bên trong tường, cửa xe và các khoang hẹp khác. Với thiết kế linh hoạt và khả năng soi chiếu rõ nét, hệ thống giúp lực lượng chức năng nhanh chóng xác minh vật thể nghi vấn một cách chính xác và an toàn.</p>','<p>A handheld X-ray screening system fitted with a compact X-ray source and detector panel, enabling mobile inspection to detect weapons and prohibited items concealed in luggage, bags, packages, parcels or inside vehicles. The device allows non-destructive inspection, and is especially effective at hard-to-reach locations such as tires, wall cavities, vehicle doors and other confined spaces. With a flexible design and sharp imaging capability, the system helps authorities quickly and safely verify suspicious objects.</p>','published',0,3,NULL,NULL,'2026-08-21 00:18:18',NULL,1,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(5,9,'Thiết bị soi chiếu cầm tay công nghệ tán xạ ngược','Handheld Backscatter X-ray Screening Device','thiet-bi-soi-chieu-cam-tay-cong-nghe-tan-xa-nguoc','handheld-backscatter-x-ray-screening-device',NULL,'Dùng để phát hiện các mối đe dọa như vũ khí, hàng lậu, thuốc nổ một cách rõ ràng và chính xác.','Used to clearly and accurately detect threats such as weapons, contraband and explosives.','<p>Dùng để phát hiện các mối đe dọa như vũ khí, hàng lậu, thuốc nổ... một cách rõ ràng và chính xác. Sử dụng công nghệ tán xạ ngược và thiết kế nhỏ gọn, cơ động, thiết bị đặc biệt hữu ích khi kiểm tra những vị trí khó tiếp cận, những vị trí mà thiết bị soi chiếu truyền thống không thể thực hiện. Bức xạ phát ra ở mức an toàn, không gây ảnh hưởng đến người vận hành hay môi trường, đảm bảo phù hợp cho việc sử dụng thường xuyên trong công tác kiểm tra, giám sát an ninh.</p>','<p>Used to clearly and accurately detect threats such as weapons, contraband and explosives. Using backscatter X-ray technology in a compact, portable design, the device is especially useful for inspecting hard-to-reach locations that conventional screening equipment cannot reach. Radiation output is at a safe level, with no impact on the operator or the environment, making it suitable for frequent use in security inspection and monitoring.</p>','published',0,4,NULL,NULL,'2026-08-21 00:18:18',NULL,1,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(6,9,'Máy soi chiếu thế hệ mới','Next-Generation X-ray Baggage Scanner','may-soi-chieu-the-he-moi','next-generation-x-ray-baggage-scanner',NULL,'Máy soi hành lý sử dụng tia X được triển khai tại các điểm kiểm tra an ninh như sân bay, nhà ga nhằm phát hiện vũ khí, chất nổ, ma túy và các vật phẩm nguy hiểm ẩn giấu trong hành lý, bưu kiện hoặc bưu phẩm.','An X-ray baggage scanner deployed at security checkpoints such as airports and stations to detect weapons, explosives, narcotics and other dangerous items concealed in luggage, parcels or mail.','<p>Máy soi hành lý sử dụng tia X được triển khai tại các điểm kiểm tra an ninh như sân bay, nhà ga... nhằm phát hiện vũ khí, chất nổ, ma túy và các vật phẩm nguy hiểm ẩn giấu trong hành lý, bưu kiện hoặc bưu phẩm. Thiết bị tích hợp công nghệ AI hiện đại, cho phép tự động nhận diện các mối đe dọa như súng, bộ phận của súng, dao… giúp tăng cường độ chính xác và rút ngắn thời gian kiểm tra. Máy soi góp phần nâng cao hiệu quả kiểm soát an ninh, giảm thiểu sai sót do yếu tố con người và hỗ trợ xử lý tình huống nhanh chóng, kịp thời.</p>','<p>An X-ray baggage scanner deployed at security checkpoints such as airports and stations to detect weapons, explosives, narcotics and other dangerous items concealed in luggage, parcels or mail. The device integrates modern AI technology to automatically recognize threats such as firearms, firearm parts and knives, improving accuracy and reducing inspection time. The scanner helps raise the effectiveness of security screening, reduce human error and support fast, timely incident response.</p>','published',0,5,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(7,9,'Hệ thống xe soi chiếu cơ động','Mobile X-ray Vehicle Screening System','he-thong-xe-soi-chieu-co-dong','mobile-x-ray-vehicle-screening-system',NULL,'Hệ thống máy soi X-ray được tích hợp trên phương tiện là giải pháp kiểm tra an ninh cơ động, triển khai nhanh chóng, đặc biệt hiệu quả tại các khu vực có hạ tầng hạn chế hoặc yêu cầu tính linh hoạt cao.','A vehicle-mounted X-ray screening system is a mobile security inspection solution that can be deployed rapidly, and is especially effective in areas with limited infrastructure or where flexibility is required.','<p>Hệ thống máy soi X-ray được tích hợp trên phương tiện là giải pháp kiểm tra an ninh cơ động, triển khai nhanh chóng, đặc biệt hiệu quả tại các khu vực có hạ tầng hạn chế hoặc yêu cầu tính linh hoạt cao. Hệ thống cho phép phát hiện, kiểm tra và xử lý nhanh các mối đe dọa tiềm ẩn như vũ khí, chất nổ hay vật phẩm nguy hiểm, đảm bảo an toàn, an ninh và giữ bí mật trong quá trình vận hành.</p>','<p>A vehicle-mounted X-ray screening system is a mobile security inspection solution that can be deployed rapidly, and is especially effective in areas with limited infrastructure or where flexibility is required. The system enables fast detection, inspection and handling of potential threats such as weapons, explosives or other dangerous items, while ensuring safety, security and confidentiality during operation.</p>','published',0,6,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(8,9,'Thiết bị phát hiện chất nổ lỏng','Liquid Explosives Detector','thiet-bi-phat-hien-chat-no-long','liquid-explosives-detector',NULL,'Là thiết bị được chuyên dùng cho các lực lượng công an, quân đội, an ninh sân bay để kiểm tra phát hiện những chất lỏng có chứa các thành phần chất nổ, chất hóa học nguy hiểm gây cháy, nổ được cất giấu trong các chai, lọ bằng chất liệu thông dụng như gốm sứ, thủy tinh, nhựa, kim loại đóng kín.','A device dedicated to police, military and airport security forces for inspecting liquids to detect explosive components or hazardous, flammable chemicals concealed in common containers such as ceramic, glass, plastic or sealed metal bottles and jars.','<p>Là thiết bị được chuyên dùng cho các lực lượng công an, quân đội, an ninh sân bay… để kiểm tra phát hiện những chất lỏng có chứa các thành phần chất nổ, chất hóa học nguy hiểm gây cháy, nổ được cất giấu trong các chai, lọ bằng chất liệu thông dụng như gốm sứ, thủy tinh, nhựa, kim loại đóng kín.</p>','<p>A device dedicated to police, military and airport security forces for inspecting liquids to detect explosive components or hazardous, flammable chemicals concealed in common containers such as ceramic, glass, plastic or sealed metal bottles and jars.</p>','published',0,7,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(9,9,'Thiết bị phát hiện chất dễ cháy, nổ dạng lỏng cầm tay','Handheld Flammable & Explosive Liquid Detector','thiet-bi-phat-hien-chat-de-chay-no-dang-long-cam-tay','handheld-flammable-explosive-liquid-detector',NULL,'Thiết bị cầm tay sử dụng công nghệ chụp phân lớp điện từ để phát hiện nhanh chóng và chính xác các chất lỏng dễ cháy, nổ bên trong bình kín mà không cần mở nắp.','A handheld device using electromagnetic tomography technology to quickly and accurately detect flammable or explosive liquids inside sealed containers without opening them.','<p>Thiết bị cầm tay sử dụng công nghệ chụp phân lớp điện từ để phát hiện nhanh chóng và chính xác các chất lỏng dễ cháy, nổ bên trong bình kín mà không cần mở nắp. Hệ thống có độ tin cậy cao, cho phép nhận diện nhiều loại chất nguy hiểm như gas, axeton, nitroglycerin, các loại cồn, ete và nhiều hợp chất dễ bay hơi khác. Thiết kế công thái học giúp thao tác thuận tiện, phù hợp với các nhiệm vụ kiểm tra an ninh và phòng chống cháy nổ.</p>','<p>A handheld device using electromagnetic tomography technology to quickly and accurately detect flammable or explosive liquids inside sealed containers without opening them. The system offers high reliability, capable of identifying a wide range of hazardous substances such as gas, acetone, nitroglycerin, various alcohols, ethers and other volatile compounds. The ergonomic design makes it convenient to operate, suited to security screening and fire-prevention tasks.</p>','published',0,8,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(10,9,'Hệ thống phát hiện chất nổ, vũ khí dạng cổng','Walk-Through Explosives & Weapons Detection Gate','he-thong-phat-hien-chat-no-vu-khi-dang-cong','walk-through-explosives-weapons-detection-gate',NULL,'Hệ thống phát hiện mối đe dọa sử dụng công nghệ sóng Centimeter kết hợp từ kế để tự động phát hiện chất nổ, vũ khí, pháo sáng, ma túy, tiền tệ ẩn giấu trong người, ba lô hoặc hành lý kéo theo thời gian thực.','A threat-detection system that uses centimeter-wave technology combined with a magnetometer to automatically detect, in real time, explosives, weapons, flares, narcotics and currency concealed on a person, in a backpack or in carry-on luggage.','<p>Hệ thống phát hiện mối đe dọa sử dụng công nghệ sóng Centimeter kết hợp từ kế để tự động phát hiện chất nổ, vũ khí, pháo sáng, ma túy, tiền tệ… ẩn giấu trong người, ba lô hoặc hành lý kéo theo thời gian thực. Hệ thống có khả năng soi quét đồng thời nhiều mục tiêu với độ chính xác cao, vùng phát hiện rộng, hỗ trợ cảnh báo bằng âm thanh, hình ảnh và đánh dấu trực quan vị trí nghi vấn.</p>','<p>A threat-detection system that uses centimeter-wave technology combined with a magnetometer to automatically detect, in real time, explosives, weapons, flares, narcotics and currency concealed on a person, in a backpack or in carry-on luggage. The system can scan multiple targets simultaneously with high accuracy over a wide detection zone, and supports audible, visual and on-screen marking of the suspect location.</p>','published',0,9,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(11,9,'Thiết bị soi gầm xe cơ động','Mobile Under-Vehicle Inspection System','thiet-bi-soi-gam-xe-co-dong','mobile-under-vehicle-inspection-system',NULL,'Hệ thống cơ động dùng để kiểm tra phương tiện, nhằm nhanh chóng phát hiện các vật thể nguy hiểm như vũ khí, chất nổ, ma túy, hàng lậu giấu dưới gầm xe mà không làm chậm luồng giao thông tại điểm kiểm tra.','A mobile system for vehicle inspection, designed to quickly detect dangerous items such as weapons, explosives, narcotics and contraband hidden under a vehicle without slowing traffic flow at the checkpoint.','<p>Hệ thống cơ động dùng để kiểm tra phương tiện, nhằm nhanh chóng phát hiện các vật thể nguy hiểm như vũ khí, chất nổ, ma túy, hàng lậu... giấu dưới gầm xe mà không làm chậm luồng giao thông tại điểm kiểm tra. Tạo ảnh độ phân giải cao, có thể soi quét toàn bộ gầm xe, bảo vệ tác động nhiễu từ ánh sáng mặt trời, tích hợp tính năng tự động phát hiện vật thể lạ.</p>','<p>A mobile system for vehicle inspection, designed to quickly detect dangerous items such as weapons, explosives, narcotics and contraband hidden under a vehicle without slowing traffic flow at the checkpoint. Produces high-resolution imagery, can scan the entire underside of a vehicle, is shielded against interference from sunlight, and includes automatic foreign-object detection.</p>','published',0,10,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(12,10,'Hệ thống giám định âm thanh thế hệ mới','Next-Generation Voice/Audio Forensics System','he-thong-giam-dinh-am-thanh-the-he-moi','next-generation-voiceaudio-forensics-system',NULL,'Giải pháp bao gồm phần cứng và phần mềm chuyên dụng, cho phép thực hiện các yêu cầu về xử lý âm thanh, phân tích và so sánh sinh trắc học giọng nói một cách chính xác và hiệu quả.','A solution comprising dedicated hardware and software that performs audio processing and voice-biometric comparison and analysis accurately and efficiently.','<p>Giải pháp bao gồm phần cứng và phần mềm chuyên dụng, cho phép thực hiện các yêu cầu về xử lý âm thanh, phân tích và so sánh sinh trắc học giọng nói một cách chính xác và hiệu quả. Hệ thống được ứng dụng rộng rãi bởi các cơ quan thực thi pháp luật, tổ chức chính phủ và các chuyên gia giám định tư nhân trên toàn thế giới trong việc nhận dạng, xác minh danh tính và hỗ trợ điều tra tội phạm thông qua dữ liệu âm thanh.</p>','<p>A solution comprising dedicated hardware and software that performs audio processing and voice-biometric comparison and analysis accurately and efficiently. The system is widely used by law enforcement agencies, government organizations and private forensic experts worldwide for identification, identity verification and criminal investigation support through audio data.</p>','published',0,0,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(13,10,'Hệ thống tổng hợp, xử lý dữ liệu âm thanh, hình ảnh (đa phương thức)','Multimodal Audio & Image Data Processing System','he-thong-tong-hop-xu-ly-du-lieu-am-thanh-hinh-anh-da-phuong-thuc','multimodal-audio-image-data-processing-system',NULL,'Hệ thống được phát triển để thu thập, xây dựng và quản lý cơ sở dữ liệu sinh trắc học dựa trên giọng nói và hình ảnh; hỗ trợ tìm kiếm, so sánh và phân tích trên quy mô lớn.','A system developed to collect, build and manage a biometric database based on voice and facial data, supporting large-scale search, comparison and analysis.','<p>Hệ thống được phát triển để thu thập, xây dựng và quản lý cơ sở dữ liệu sinh trắc học dựa trên giọng nói và hình ảnh; hỗ trợ tìm kiếm, so sánh và phân tích trên quy mô lớn. Khi tiếp nhận số lượng lớn tệp âm thanh chứa một hoặc nhiều người nói, hệ thống cho phép nhận diện và đối sánh từng giọng nói với các mẫu đã lưu trong cơ sở dữ liệu, từ đó xác định khả năng trùng khớp. Đối với dữ liệu hình ảnh, hệ thống hỗ trợ nhận dạng khuôn mặt và đối chiếu với dữ liệu lưu trữ sẵn có, kể cả khi trong một tệp có nhiều khuôn mặt. Ngoài ra, hệ thống tích hợp khả năng phân tích nâng cao nhằm phát hiện và làm rõ mối liên hệ giữa các đối tượng trong tập dữ liệu âm thanh đầu vào.</p>','<p>A system developed to collect, build and manage a biometric database based on voice and facial data, supporting large-scale search, comparison and analysis. When ingesting a large volume of audio files containing one or more speakers, the system identifies and matches each voice against samples stored in the database to determine potential matches. For image data, the system supports facial recognition and comparison against existing records, even when a single file contains multiple faces. The system also includes advanced analytics to detect and clarify relationships between subjects within the input audio dataset.</p>','published',0,1,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(14,10,'Hệ thống nhận diện khuôn mặt','Facial Recognition System','he-thong-nhan-dien-khuon-mat','facial-recognition-system',NULL,'Giải pháp giám sát an ninh tích hợp ứng dụng công nghệ trí tuệ nhân tạo (AI), cho phép phát hiện và nhận dạng khuôn mặt, kiểm soát truy cập, phân loại phương tiện trong thời gian thực.','An AI-powered security surveillance solution enabling real-time face detection and recognition, access control and vehicle classification.','<p>Giải pháp giám sát an ninh tích hợp ứng dụng công nghệ trí tuệ nhân tạo (AI), cho phép phát hiện và nhận dạng khuôn mặt, kiểm soát truy cập, phân loại phương tiện… trong thời gian thực. Hệ thống có khả năng xử lý dữ liệu video chất lượng thấp với độ chính xác nhận dạng cao, đồng thời hỗ trợ quản lý đồng thời nhiều camera và theo dõi hành trình đối tượng. Kiến trúc hệ thống được thiết kế mở và linh hoạt, dễ dàng tích hợp với mạng lưới CCTV đô thị, các trung tâm điều hành giám sát và các hệ thống bảo mật hiện có.</p>','<p>An AI-powered security surveillance solution enabling real-time face detection and recognition, access control and vehicle classification. The system can process low-quality video data with high recognition accuracy, while supporting simultaneous management of multiple cameras and subject-journey tracking. Its architecture is open and flexible, integrating easily with urban CCTV networks, monitoring/command centers and existing security systems.</p>','published',0,2,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(15,10,'Hệ thống phân tích phản ứng và cảm xúc qua giọng nói','Voice Stress & Emotion Analysis System','he-thong-phan-tich-phan-ung-va-cam-xuc-qua-giong-noi','voice-stress-emotion-analysis-system',NULL,'Hệ thống phân tích phản ứng và cảm xúc qua giọng nói đóng vai trò hỗ trợ hiệu quả lực lượng an ninh điều tra trong việc phát hiện các cảm xúc tiềm ẩn liên quan đến hành vi nói dối.','A voice stress and emotion analysis system that effectively supports security investigators in detecting hidden emotions associated with deceptive behavior.','<p>Hệ thống phân tích phản ứng và cảm xúc qua giọng nói đóng vai trò hỗ trợ hiệu quả lực lượng an ninh điều tra trong việc phát hiện các cảm xúc tiềm ẩn liên quan đến hành vi nói dối. Thông qua việc giải mã tín hiệu cảm xúc trong giọng nói, hệ thống giúp các nhà điều tra và giám sát hiểu rõ hơn về động cơ, trạng thái tâm lý và mức độ thành thật của đối tượng, từ đó nâng cao độ chính xác và hiệu quả trong quá trình đánh giá, thẩm vấn và ra quyết định.</p>','<p>A voice stress and emotion analysis system that effectively supports security investigators in detecting hidden emotions associated with deceptive behavior. By decoding emotional signals in speech, the system helps investigators and monitoring personnel better understand a subject&#039;s motives, psychological state and level of honesty, improving the accuracy and effectiveness of assessment, interrogation and decision-making.</p>','published',0,3,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(16,10,'Phần mềm phân tích dữ liệu điện tử','Digital Forensics Analysis Software','phan-mem-phan-tich-du-lieu-dien-tu','digital-forensics-analysis-software',NULL,'Phân tích dữ liệu điện tử từ thiết bị của nghi phạm (lịch, danh bạ, cuộc gọi, tin nhắn Whatsapp, Telegram, Facebook ) nhằm hình thành đường dây đối tượng phục vụ mở rộng điều tra; bao gồm khôi phục tin nhắn đã xóa, phân tích các hoạt động trên mạng xã hội để tìm ra các mối liên kết giữa nghi phạm và các đối tượng liên quan, giúp phát hiện các mối quan hệ hoặc những thông tin tiềm ẩn trên không gian mạng.','Analyzes electronic data from a suspect\'s device (calendar, contacts, calls, WhatsApp, Telegram, Facebook messages, etc.) to build a network of associates for expanded investigation; includes recovery of deleted messages and analysis of social-media activity to uncover links between the suspect and related parties, helping to reveal relationships or hidden information in cyberspace.','<p>Phân tích dữ liệu điện tử từ thiết bị của nghi phạm (lịch, danh bạ, cuộc gọi, tin nhắn Whatsapp, Telegram, Facebook…) nhằm hình thành đường dây đối tượng phục vụ mở rộng điều tra; bao gồm khôi phục tin nhắn đã xóa, phân tích các hoạt động trên mạng xã hội để tìm ra các mối liên kết giữa nghi phạm và các đối tượng liên quan, giúp phát hiện các mối quan hệ hoặc những thông tin tiềm ẩn trên không gian mạng.</p>','<p>Analyzes electronic data from a suspect&#039;s device (calendar, contacts, calls, WhatsApp, Telegram, Facebook messages, etc.) to build a network of associates for expanded investigation; includes recovery of deleted messages and analysis of social-media activity to uncover links between the suspect and related parties, helping to reveal relationships or hidden information in cyberspace.</p>','published',0,4,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:42',NULL),(17,10,'Hệ thống phân tích phản ứng và cảm xúc qua giọng nói hỗ trợ công tác điều tra thẩm vấn','Voice Stress & Emotion Analysis System for Interrogation Support','he-thong-phan-tich-phan-ung-va-cam-xuc-qua-giong-noi-ho-tro-cong-tac-dieu-tra-tham-van','voice-stress-emotion-analysis-system-for-interrogation-support',NULL,'Hệ thống có khả năng phát hiện ra những cảm xúc liên quan đằng sau lời nói dối, giúp các nhà điều tra, giám sát hiểu rõ động cơ của lời nói.','The system can detect the emotions underlying a deceptive statement, helping investigators and monitoring staff understand the motive behind what is said.','<p>Hệ thống có khả năng phát hiện ra những cảm xúc liên quan đằng sau lời nói dối, giúp các nhà điều tra, giám sát hiểu rõ động cơ của lời nói. Công nghệ này xác định nhiều loại mức độ căng thẳng, quá trình nhận thức và phản ứng cảm xúc được phản ánh trong các đặc tính khác nhau của giọng nói, cung cấp thông tin chi tiết về cách người nói suy nghĩ, điều gì khiến người nói bận tâm, phấn khích, những phần nào trong bài phát biểu mà người nói không chắc chắn, và những lĩnh vực nào có vẻ là vấn đề nhạy cảm đối với người nói.</p>','<p>The system can detect the emotions underlying a deceptive statement, helping investigators and monitoring staff understand the motive behind what is said. The technology identifies various levels of stress, cognitive load and emotional response reflected in different characteristics of speech, providing detailed insight into how the speaker is thinking, what concerns or excites them, which parts of their statement they are uncertain about, and which areas appear to be sensitive topics for the speaker.</p>','published',0,5,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(18,10,'Thiết bị phân tích và tạo mẫu vân tay chuyên dụng','Specialized Fingerprint Analysis & Reproduction System','thiet-bi-phan-tich-va-tao-mau-van-tay-chuyen-dung','specialized-fingerprint-analysis-reproduction-system',NULL,'Thiết bị được sử dụng để thu nhận, xử lý, nâng cao chất lượng và tái tạo dấu vân tay từ các nguồn dữ liệu điện tử hoặc mẫu dấu vân tay thu thập được trong quá trình điều tra.','A device used to capture, process, enhance and reconstruct fingerprints from electronic data sources or fingerprint samples collected during an investigation.','<p>Thiết bị được sử dụng để thu nhận, xử lý, nâng cao chất lượng và tái tạo dấu vân tay từ các nguồn dữ liệu điện tử hoặc mẫu dấu vân tay thu thập được trong quá trình điều tra. Hệ thống hỗ trợ phân tích các đặc trưng nhận dạng của dấu vân tay, đánh giá chất lượng mẫu và tạo mẫu dấu vân tay vật lý có độ chính xác cao phục vụ công tác giám định kỹ thuật hình sự, điều tra số, an ninh, quốc phòng và nghiên cứu sinh trắc học. Giải pháp gồm hai phiên bản triển khai: phiên bản cơ động tác chiến (thiết kế nhỏ gọn, dễ vận chuyển, triển khai nhanh tại hiện trường) và phiên bản cố định phòng kỹ thuật/phòng giám định (tối ưu cho môi trường phòng thí nghiệm, vận hành liên tục với khối lượng lớn). Hệ thống cung cấp quy trình khép kín từ thu nhận dữ liệu, xử lý ảnh, phân tích đặc trưng đến tái tạo và mô phỏng dấu vân tay.</p>','<p>A device used to capture, process, enhance and reconstruct fingerprints from electronic data sources or fingerprint samples collected during an investigation. The system supports analysis of fingerprint identification features, sample-quality assessment, and high-precision physical fingerprint reproduction for forensic examination, digital investigation, security, defense and biometric research. The solution comes in two deployment versions: a field-operations version (compact design, easy to transport, rapid on-site deployment for investigation, tracing, subject identification and field operations) and a fixed laboratory version (optimized for laboratory environments, supporting continuous, high-volume operation for forensic examination, research, training and biometric system evaluation). The system provides an end-to-end workflow from data capture and image processing to feature analysis, reconstruction and fingerprint simulation.</p>','published',0,6,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:27:13',NULL),(19,10,'Hệ thống trích xuất và phân tích dữ liệu điện tử','Digital Data Extraction & Analysis System','he-thong-trich-xuat-va-phan-tich-du-lieu-dien-tu','digital-data-extraction-analysis-system',NULL,'Hệ thống được sử dụng để thu thập, trích xuất, sao lưu, phục hồi và phân tích dữ liệu điện tử từ nhiều nguồn khác nhau như ổ cứng HDD/SSD, thiết bị lưu trữ Flash, USB, thẻ nhớ, hệ thống ghi hình DVR/NVR/CCTV, các thiết bị điện tử trên phương tiện giao thông và các thiết bị số khác.','A system used to collect, extract, back up, recover and analyze electronic data from a wide range of sources, including HDD/SSD drives, Flash storage devices, USB drives, memory cards, DVR/NVR/CCTV recording systems, in-vehicle electronic devices and other digital devices.','<p>Hệ thống được sử dụng để thu thập, trích xuất, sao lưu, phục hồi và phân tích dữ liệu điện tử từ nhiều nguồn khác nhau như ổ cứng HDD/SSD, thiết bị lưu trữ Flash, USB, thẻ nhớ, hệ thống ghi hình DVR/NVR/CCTV, các thiết bị điện tử trên phương tiện giao thông và các thiết bị số khác. Hệ thống hỗ trợ truy cập dữ liệu ở mức vật lý và logic, tạo bản sao pháp chứng, khôi phục dữ liệu bị xóa, bị ghi đè một phần hoặc bị hư hỏng do lỗi phần cứng, lỗi firmware, lỗi hệ thống tệp tin và các nguyên nhân khác. Hệ thống cho phép phân tích cấu trúc dữ liệu, lịch sử hoạt động, dữ liệu người dùng, dữ liệu định vị, nhật ký hệ thống, dữ liệu đa phương tiện và các chứng cứ điện tử liên quan, phục vụ công tác điều tra, giám định kỹ thuật số, phòng chống tội phạm sử dụng công nghệ cao.</p>','<p>A system used to collect, extract, back up, recover and analyze electronic data from a wide range of sources, including HDD/SSD drives, Flash storage devices, USB drives, memory cards, DVR/NVR/CCTV recording systems, in-vehicle electronic devices and other digital devices. The system supports both physical- and logical-level data access, creates forensic copies, and recovers data that has been deleted, partially overwritten, or damaged due to hardware failure, firmware faults, file-system errors and other causes. Using dedicated tools, the system can analyze data structure, activity history, user data, location data, system logs, multimedia data and related electronic evidence, supporting investigation, digital forensic examination, high-tech crime prevention, digital data analysis, and helping to clarify relationships, behaviors, events or digital traces relevant to a case.</p>','published',0,7,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(20,11,'Hệ thống thiết bị dò rệp nghe lén lợi dụng đường dây, đường dây mạng, đường điện lưới','Wiretap Detection System for Telephone Lines, Network Cables & Power Lines','he-thong-thiet-bi-do-rep-nghe-len-loi-dung-duong-day-duong-day-mang-duong-dien-luoi','wiretap-detection-system-for-telephone-lines-network-cables-power-lines',NULL,'Dùng để đo kiểm, phân tích các loại đường dây như đường dây điện thoại, đường dây báo động, báo cháy nhằm phát hiện thiết bị nghe trộm và các mối đe dọa khác.','Used to measure and analyze various types of lines such as telephone lines, alarm and fire-alarm lines to detect eavesdropping devices and other threats.','<p>Dùng để đo kiểm, phân tích các loại đường dây như đường dây điện thoại, đường dây báo động, báo cháy nhằm phát hiện thiết bị nghe trộm và các mối đe dọa khác. Thiết bị sử dụng kết hợp nhiều kiểu kiểm tra đường dây gồm điện áp, dòng, trở kháng, điện dung và các công nghệ mới đảm bảo hiệu quả phát hiện tối đa.</p>','<p>Used to measure and analyze various types of lines such as telephone lines, alarm and fire-alarm lines to detect eavesdropping devices and other threats. The device combines multiple line-testing methods — voltage, current, impedance, capacitance — together with newer technologies to ensure maximum detection effectiveness.</p>','published',0,0,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(21,11,'Thiết bị phát hiện thiết bị nghe lén lợi dụng sóng RF','RF Bug & Wireless Eavesdropping Detector','thiet-bi-phat-hien-thiet-bi-nghe-len-loi-dung-song-rf','rf-bug-wireless-eavesdropping-detector',NULL,'Thiết bị phân tích phổ cầm tay là công cụ lý tưởng dành cho các cơ quan thực thi pháp luật trong công tác khảo sát hệ thống truyền thông, phân tích và định vị các nguồn phát sóng vô tuyến, cũng như đánh giá việc sử dụng kênh thông tin liên lạc.','A handheld spectrum analyzer that is an ideal tool for law enforcement agencies conducting communications-network surveys, analyzing and locating radio-frequency emission sources, and assessing use of communication channels.','<p>Thiết bị phân tích phổ cầm tay là công cụ lý tưởng dành cho các cơ quan thực thi pháp luật trong công tác khảo sát hệ thống truyền thông, phân tích và định vị các nguồn phát sóng vô tuyến, cũng như đánh giá việc sử dụng kênh thông tin liên lạc. Ngoài ra, thiết bị còn đóng vai trò quan trọng trong điều tra các hành vi lạm dụng phổ tần và phát hiện các thiết bị thu phát không dây trái phép. Với thiết kế nhỏ gọn, cơ động, thiết bị phù hợp sử dụng tại hiện trường, góp phần nâng cao hiệu quả giám sát, đảm bảo an ninh thông tin và an toàn truyền thông.</p>','<p>A handheld spectrum analyzer that is an ideal tool for law enforcement agencies conducting communications-network surveys, analyzing and locating radio-frequency emission sources, and assessing use of communication channels. The device also plays an important role in investigating spectrum-abuse activity and detecting unauthorized wireless transmit/receive devices. With a compact, portable design, the device is suited to field use and helps improve surveillance effectiveness, information security and safe communications.</p>','published',0,1,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(22,11,'Thiết bị phát hiện ống kính quang học','Hidden Camera Lens Detector','thiet-bi-phat-hien-ong-kinh-quang-hoc','hidden-camera-lens-detector',NULL,'Thiết bị cầm tay, nhỏ gọn được thiết kế chuyên biệt để phát hiện các camera giám sát ẩn, hoạt động dựa trên nguyên lý phản xạ ánh sáng từ ống kính quang học.','A compact, handheld device specifically designed to detect hidden surveillance cameras, operating on the principle of light reflection from an optical camera lens.','<p>Thiết bị cầm tay, nhỏ gọn được thiết kế chuyên biệt để phát hiện các camera giám sát ẩn, hoạt động dựa trên nguyên lý phản xạ ánh sáng từ ống kính quang học. Với nhiều chế độ vận hành linh hoạt cùng thiết kế công thái, thiết bị mang lại sự tiện dụng trong quá trình sử dụng. Ngoài ra, người dùng có thể kết hợp sử dụng smartphone để chụp ảnh hoặc quay video hiện trường, hỗ trợ công tác báo cáo và lưu trữ thông tin.</p>','<p>A compact, handheld device specifically designed to detect hidden surveillance cameras, operating on the principle of light reflection from an optical camera lens. With multiple flexible operating modes and an ergonomic design, the device is convenient to use. Users can also pair it with a smartphone to photograph or video the scene, supporting reporting and record-keeping.</p>','published',0,2,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(23,11,'Thiết bị dò linh kiện phi tuyến','Non-Linear Junction Detector','thiet-bi-do-linh-kien-phi-tuyen','non-linear-junction-detector',NULL,'Thiết bị được thiết kế để dò tìm, phát hiện và xác định vị trí của các thiết bị điện tử giấu kín, thiết bị nghe lén trái phép trong những khu vực yêu cầu đảm bảo an ninh, an toàn ngay cả khi các thiết bị mục tiêu đang tắt nguồn.','A device designed to search for, detect and locate concealed electronic devices and unauthorized eavesdropping equipment in areas requiring high security, even when the target device is powered off.','<p>Thiết bị được thiết kế để dò tìm, phát hiện và xác định vị trí của các thiết bị điện tử giấu kín, thiết bị nghe lén trái phép trong những khu vực yêu cầu đảm bảo an ninh, an toàn ngay cả khi các thiết bị mục tiêu đang tắt nguồn. Thiết bị có thể phát hiện cả các mạch nhỏ, hiện đại sử dụng linh kiện dán bề mặt lẫn các mạch đời cũ được giấu trong các vật liệu có mật độ cao. Cảnh báo được đưa ra dưới dạng âm thanh và tín hiệu trực quan, giúp người dùng nhận biết và xác định chính xác vị trí nghi vấn một cách dễ dàng và hiệu quả.</p>','<p>A device designed to search for, detect and locate concealed electronic devices and unauthorized eavesdropping equipment in areas requiring high security, even when the target device is powered off. The device can detect both small, modern circuits built with surface-mount components and older-generation circuits hidden within high-density materials. Alerts are given as both an audible tone and a visual signal, helping the user easily and effectively identify and pinpoint a suspect location.</p>','published',0,3,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(24,11,'Hệ thống phát hiện nghe lén thông minh 24/7','24/7 Smart Eavesdropping Detection System','he-thong-phat-hien-nghe-len-thong-minh-247','247-smart-eavesdropping-detection-system',NULL,'Hệ thống được thiết kế để giám sát vô tuyến từ xa, liên tục trong khu vực cần đảm bảo an toàn an ninh; với mục tiêu chính là phát hiện các tín hiệu bất thường và định vị chính xác nguồn phát nhằm ngăn chặn các hành vi nghe lén, phát tán thông tin trái phép.','A system designed to provide continuous, remote radio-frequency monitoring of an area requiring security protection, with the primary goal of detecting abnormal signals and accurately locating their source in order to prevent eavesdropping and unauthorized dissemination of information.','<p>Hệ thống được thiết kế để giám sát vô tuyến từ xa, liên tục trong khu vực cần đảm bảo an toàn an ninh; với mục tiêu chính là phát hiện các tín hiệu bất thường và định vị chính xác nguồn phát nhằm ngăn chặn các hành vi nghe lén, phát tán thông tin trái phép.</p>','<p>A system designed to provide continuous, remote radio-frequency monitoring of an area requiring security protection, with the primary goal of detecting abnormal signals and accurately locating their source in order to prevent eavesdropping and unauthorized dissemination of information.</p>','published',0,4,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(25,12,'Hệ thống phát hiện bắn tỉa','Sniper Detection System','he-thong-phat-hien-ban-tia','sniper-detection-system',NULL,'Hệ thống được thiết kế để thực hiện giám sát tự động, từ xa trong cả dải quang phổ nhìn thấy và hồng ngoại, hỗ trợ hiệu quả cho các lực lượng thực thi pháp luật trong nhiệm vụ bảo vệ biên giới, giám sát bờ biển, phát hiện vị trí bắn tỉa, chống khủng bố, phòng chống gián điệp và bảo vệ các khu vực trọng yếu.','A system designed for automated, remote surveillance across both the visible and infrared spectral bands, effectively supporting law enforcement forces in border protection, coastal surveillance, sniper-position detection, counter-terrorism, counter-espionage and protection of critical areas.','<p>Hệ thống được thiết kế để thực hiện giám sát tự động, từ xa trong cả dải quang phổ nhìn thấy và hồng ngoại, hỗ trợ hiệu quả cho các lực lượng thực thi pháp luật trong nhiệm vụ bảo vệ biên giới, giám sát bờ biển, phát hiện vị trí bắn tỉa, chống khủng bố, phòng chống gián điệp và bảo vệ các khu vực trọng yếu. Thiết bị có khả năng phát hiện các thiết bị quang học và quang-điện tử, cũng như đo xa mục tiêu với độ chính xác cao.</p>','<p>A system designed for automated, remote surveillance across both the visible and infrared spectral bands, effectively supporting law enforcement forces in border protection, coastal surveillance, sniper-position detection, counter-terrorism, counter-espionage and protection of critical areas. The device can detect optical and opto-electronic devices, as well as measure target range with high accuracy. With advanced technology integration and the ability to operate without direct contact with the target, the system provides a comprehensive, proactive and effective surveillance solution for complex security situations.</p>','published',0,0,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(26,12,'Hệ thống quay chụp ngày đêm','Day/Night Observation & Recording System','he-thong-quay-chup-ngay-dem','daynight-observation-recording-system',NULL,'Thiết bị cầm tay được thiết kế chuyên biệt nhằm hỗ trợ lực lượng thực thi pháp luật trong việc giám sát video liên tục ngày đêm, bất kể điều kiện thời tiết khắc nghiệt như sương mù, mưa hoặc tuyết rơi.','A handheld device specifically designed to help law enforcement forces maintain continuous day-and-night video surveillance, regardless of harsh weather conditions such as fog, rain or snow.','<p>Thiết bị cầm tay được thiết kế chuyên biệt nhằm hỗ trợ lực lượng thực thi pháp luật trong việc giám sát video liên tục ngày đêm, bất kể điều kiện thời tiết khắc nghiệt như sương mù, mưa hoặc tuyết rơi. Thiết bị có khả năng phát hiện các thiết bị quang học đối diện đang được sử dụng để quan sát hoặc ngắm bắn. Ngoài ra, thiết bị cho phép quan sát xuyên qua kính màu và kính phản quang của tòa nhà hoặc phương tiện, và có tính năng đo khoảng cách đến đối tượng quan sát.</p>','<p>A handheld device specifically designed to help law enforcement forces maintain continuous day-and-night video surveillance, regardless of harsh weather conditions such as fog, rain or snow. The device can detect opposing optical devices being used for observation or aiming, improving proactive counter-surveillance and anti-ambush capability. It also allows observation through tinted or reflective glass on buildings or vehicles, extending the surveillance range in shielded areas. A rangefinder feature helps accurately determine the position and distance of the observed subject, supporting situational assessment and tactical decision-making.</p>','published',0,1,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(27,12,'Thiết bị soi khe hẹp','Narrow-Gap Inspection Scope System','thiet-bi-soi-khe-hep','narrow-gap-inspection-scope-system',NULL,'Bộ thiết bị chuyên dụng dành cho lực lượng an ninh, cho phép kiểm tra bí mật và quan sát trực quan các khu vực khó tiếp cận thông qua khe cửa hẹp, lỗ nhỏ Thiết bị có khả năng chụp ảnh, quay video chất lượng cao và lưu trữ phục vụ làm bằng chứng.','A dedicated equipment set for security forces, enabling covert inspection and visual observation of hard-to-reach areas through narrow door gaps, small holes and similar openings.','<p>Bộ thiết bị chuyên dụng dành cho lực lượng an ninh, cho phép kiểm tra bí mật và quan sát trực quan các khu vực khó tiếp cận thông qua khe cửa hẹp, lỗ nhỏ... Thiết bị có khả năng chụp ảnh, quay video chất lượng cao và lưu trữ phục vụ làm bằng chứng. Tích hợp màn hình hỗ trợ xem và điều khiển hướng nhìn trực tiếp. Hoạt động cơ động, độc lập nhờ sử dụng pin sạc lại.</p>','<p>A dedicated equipment set for security forces, enabling covert inspection and visual observation of hard-to-reach areas through narrow door gaps, small holes and similar openings. The device can capture high-quality photos and video for evidentiary purposes. It integrates a screen for viewing and direct control of the viewing direction, and operates mobile and independently using a rechargeable battery.</p>','published',0,2,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(28,12,'Máy ghi âm kỹ thuật số','Digital Voice Recorder','may-ghi-am-ky-thuat-so','digital-voice-recorder',NULL,'Thiết bị được thiết kế để ghi âm thanh mono chất lượng cao từ khoảng cách xa, ngay cả trong các môi trường âm thanh phức tạp.','A device designed to record high-quality mono audio from a distance, even in complex acoustic environments.','<p>Thiết bị được thiết kế để ghi âm thanh mono chất lượng cao từ khoảng cách xa, ngay cả trong các môi trường âm thanh phức tạp. Với kích thước nhỏ gọn, trọng lượng nhẹ và vỏ kim loại bền chắc, thiết bị phù hợp cho các nhiệm vụ ghi âm kín đáo. Người dùng có thể kích hoạt ghi âm bằng công tắc, kích hoạt giọng nói hoặc lập lịch ghi thông qua bộ định thời. Dữ liệu ghi được mã hóa và chỉ có thể truy cập thông qua phần mềm chuyên dụng đi kèm.</p>','<p>A device designed to record high-quality mono audio from a distance, even in complex acoustic environments. Compact, lightweight and housed in a durable metal casing, the device is suited to covert recording tasks. Users can start recording via a switch, voice activation, or a scheduled timer. Recorded data is encrypted and can only be accessed through dedicated companion software.</p>','published',0,3,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(29,12,'Thiết bị ghi âm thanh định hướng','Directional Audio Recorder','thiet-bi-ghi-am-thanh-dinh-huong','directional-audio-recorder',NULL,'Thiết bị ghi âm chuyên dụng, được thiết kế để hoạt động hiệu quả trong môi trường có nhiều tạp âm.','A dedicated recording device designed to operate effectively in noisy environments.','<p>Thiết bị ghi âm chuyên dụng, được thiết kế để hoạt động hiệu quả trong môi trường có nhiều tạp âm. Bằng cách sử dụng tổ hợp nhiều microphone cùng với thuật toán xử lý tín hiệu tiên tiến, thiết bị có khả năng nâng cao độ rõ của tiếng nói đến từ một hướng xác định, đồng thời loại bỏ phần lớn âm thanh nhiễu từ môi trường xung quanh. Tích hợp camera cho phép người dùng dễ dàng xác định và tập trung vào hướng âm thanh cần quan tâm. Thiết bị có thể được điều khiển từ xa thông qua kết nối Wi-Fi, sử dụng smartphone như một công cụ điều khiển tiện lợi.</p>','<p>A dedicated recording device designed to operate effectively in noisy environments. Using a microphone array combined with advanced signal-processing algorithms, the device enhances the clarity of speech arriving from a specified direction while suppressing most ambient noise. An integrated camera lets the user easily identify and focus on the direction of interest. The device includes companion speech-processing software supporting both live and post-processing, and can also be remote-controlled via Wi-Fi using a smartphone as a convenient control tool.</p>','published',0,4,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(30,12,'Micro laser quang âm','Laser Acoustic Microphone','micro-laser-quang-am','laser-acoustic-microphone',NULL,'Thiết bị thu âm từ xa ứng dụng công nghệ chiếu tia laser vô hình (bước sóng 1550 nm) lên các bề mặt như kính, kim loại, giấy, vải hoặc nhựa để thu dao động âm thanh mà không cần tiếp cận trực tiếp.','A long-range audio pickup device using an invisible laser beam (1550 nm wavelength) projected onto surfaces such as glass, metal, paper or plastic to capture acoustic vibrations without direct contact.','<p>Thiết bị thu âm từ xa ứng dụng công nghệ chiếu tia laser vô hình (bước sóng 1550 nm) lên các bề mặt như kính, kim loại, giấy, vải hoặc nhựa để thu dao động âm thanh mà không cần tiếp cận trực tiếp. Cho phép ghi âm hoặc nghe lén hội thoại trong không gian kín như phòng họp, ô tô… từ khoảng cách lên đến vài trăm mét. Quá trình giám sát hoàn toàn bí mật, không để lại dấu vết và đảm bảo an toàn cho mắt nhờ sử dụng tia laser bước sóng phù hợp.</p>','<p>A long-range audio pickup device using an invisible laser beam (1550 nm wavelength) projected onto surfaces such as glass, metal, paper or plastic to capture acoustic vibrations without direct contact. It enables recording or monitoring of conversations inside enclosed spaces such as meeting rooms or vehicles from a distance of up to several hundred meters. Surveillance is fully covert, leaves no trace, and is eye-safe thanks to the use of an appropriate laser wavelength.</p>','published',0,5,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(31,12,'Microphone quang','Optical Microphone','microphone-quang','optical-microphone',NULL,'Microphone quang độ nhạy cao được thiết kế chuyên biệt cho mục đích giám sát âm thanh bí mật từ khoảng cách xa, hoạt động hiệu quả ngay cả trong môi trường khắc nghiệt.','A high-sensitivity optical microphone specifically designed for covert long-range audio surveillance, operating effectively even in harsh environments.','<p>Microphone quang độ nhạy cao được thiết kế chuyên biệt cho mục đích giám sát âm thanh bí mật từ khoảng cách xa, hoạt động hiệu quả ngay cả trong môi trường khắc nghiệt. Cấu tạo từ nhựa và thủy tinh, không chứa linh kiện điện tử hay kim loại, giúp thiết bị chống can nhiễu điện từ tối ưu và giảm thiểu nguy cơ bị phát hiện.</p>','<p>A high-sensitivity optical microphone specifically designed for covert long-range audio surveillance, operating effectively even in harsh environments. Constructed from plastic and glass with no electronic or metal components, the device offers optimal resistance to electromagnetic interference and minimizes the risk of detection.</p>','published',0,6,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(32,12,'Bộ thu phát tiếng đa chức năng','Multi-Function Audio Transceiver','bo-thu-phat-tieng-da-chuc-nang','multi-function-audio-transceiver',NULL,'Thiết bị giám sát âm thanh từ xa cho phép ghi âm trong phòng với chất lượng cao, dữ liệu được lưu trực tiếp vào thẻ nhớ.','A remote audio-surveillance device enabling high-quality in-room recording, with data stored directly to a memory card.','<p>Thiết bị giám sát âm thanh từ xa cho phép ghi âm trong phòng với chất lượng cao, dữ liệu được lưu trực tiếp vào thẻ nhớ. Hệ thống hoạt động độc lập nhờ sử dụng pin sạc lại, tiêu thụ năng lượng thấp, phù hợp cho các nhiệm vụ giám sát kéo dài.</p>','<p>A remote audio-surveillance device enabling high-quality in-room recording, with data stored directly to a memory card. The system operates independently using a rechargeable battery with low power consumption, suited to extended monitoring tasks.</p>','published',0,7,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(33,12,'Thiết bị ghi hình Full HD siêu mỏng có khả năng điều khiển từ xa','Ultra-Thin Full HD Recording Device with Remote Control','thiet-bi-ghi-hinh-full-hd-sieu-mong-co-kha-nang-dieu-khien-tu-xa','ultra-thin-full-hd-recording-device-with-remote-control',NULL,'Thiết bị được thiết kế để ghi lại video chất lượng cao với độ phân giải Full HD và lưu trữ trực tiếp vào thẻ nhớ.','A device designed to capture high-quality Full HD video and store it directly to a memory card.','<p>Thiết bị được thiết kế để ghi lại video chất lượng cao với độ phân giải Full HD và lưu trữ trực tiếp vào thẻ nhớ. Thiết bị áp dụng thuật toán mã hóa AES256 để ngăn chặn truy cập trái phép vào các tệp ghi hình, tích hợp bộ định thời gian ghi và có khả năng kích hoạt ghi tự động thông qua chức năng kích hoạt giọng nói. Quá trình bắt đầu hoặc dừng ghi có thể được điều khiển từ xa, thiết lập qua phần mềm chuyên dụng với giao diện thân thiện.</p>','<p>A device designed to capture high-quality Full HD video and store it directly to a memory card. The device applies AES-256 encryption to prevent unauthorized access to recorded files, includes a recording timer, and supports automatic recording activation via voice trigger. Recording can be started or stopped remotely, with settings and file management handled through dedicated software with a user-friendly interface.</p>','published',0,8,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(34,12,'Bộ thu phát hình tiếng kỹ thuật số đa chức năng','Multi-Function Digital Audio/Video Transceiver','bo-thu-phat-hinh-tieng-ky-thuat-so-da-chuc-nang','multi-function-digital-audiovideo-transceiver',NULL,'Thiết bị được thiết kế để ghi video và truyền dữ liệu đã mã hóa qua đường truyền vô tuyến sử dụng kỹ thuật điều chế COFDM, đảm bảo khả năng truyền dẫn hình ảnh chất lượng cao, ổn định trong các điều kiện tín hiệu phức tạp.','A device designed to record video and transmit encrypted data over a wireless link using COFDM modulation, ensuring high-quality, stable image transmission under complex signal conditions such as motion, line-of-sight obstruction or interference.','<p>Thiết bị được thiết kế để ghi video và truyền dữ liệu đã mã hóa qua đường truyền vô tuyến sử dụng kỹ thuật điều chế COFDM, đảm bảo khả năng truyền dẫn hình ảnh chất lượng cao, ổn định trong các điều kiện tín hiệu phức tạp. Với thiết kế siêu mỏng và kích thước nhỏ gọn, thiết bị dễ dàng tích hợp vào các chi tiết ngụy trang khác nhau. Thiết bị cho phép ghi âm thanh và video tại bộ phát, truyền hình ảnh trực tiếp đến bộ thu với độ trễ cực thấp, và điều khiển bộ phát từ xa thông qua bộ thu. Dữ liệu lưu trữ và truyền đều được bảo mật bằng mã hóa AES256.</p>','<p>A device designed to record video and transmit encrypted data over a wireless link using COFDM modulation, ensuring high-quality, stable image transmission under complex signal conditions such as motion, line-of-sight obstruction or interference. With an ultra-thin, compact design, the device is easy to integrate into various forms of concealment for missions requiring high covertness. It can record audio and video at the transmitter while streaming live imagery to the receiver with extremely low latency, and the transmitter can be remote-controlled from the receiver. Both stored and transmitted data are secured using AES-256 encryption.</p>','published',0,9,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(35,12,'Hệ thống khoan tường bí mật','Covert Wall-Drilling System','he-thong-khoan-tuong-bi-mat','covert-wall-drilling-system',NULL,'Hệ thống khoan tường độ ồn cực thấp được thiết kế chuyên biệt cho các nhiệm vụ yêu cầu tính kín đáo, cho phép khoan các lỗ nhỏ mà không gây chú ý.','An ultra-low-noise wall-drilling system specifically designed for tasks requiring discretion, enabling small holes to be drilled without drawing attention.','<p>Hệ thống khoan tường độ ồn cực thấp được thiết kế chuyên biệt cho các nhiệm vụ yêu cầu tính kín đáo, cho phép khoan các lỗ nhỏ mà không gây chú ý. Thiết bị hỗ trợ khoan hiệu quả trên nhiều loại vật liệu như bê tông, xi măng, gạch…, phù hợp sử dụng trong các hoạt động giám sát, trinh sát và kỹ thuật nghiệp vụ đặc biệt.</p>','<p>An ultra-low-noise wall-drilling system specifically designed for tasks requiring discretion, enabling small holes to be drilled without drawing attention. The device drills effectively into a variety of materials such as concrete, cement and brick, and is suited to surveillance, reconnaissance and special technical operations.</p>','published',0,10,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(36,12,'Hệ thống soi lỗ khóa chuyên dụng','Dedicated Keyhole Scanning System','he-thong-soi-lo-khoa-chuyen-dung','dedicated-keyhole-scanning-system',NULL,'Hệ thống soi lỗ khóa sử dụng sóng siêu âm được thiết kế để giải mã hầu hết các loại khóa cơ học hiện nay.','A keyhole-scanning system using ultrasound technology designed to decode most current mechanical locks.','<p>Hệ thống soi lỗ khóa sử dụng sóng siêu âm được thiết kế để giải mã hầu hết các loại khóa cơ học hiện nay. Bằng cách sử dụng công nghệ siêu âm, hệ thống cho phép quét và tái tạo chi tiết cơ chế bên trong của ổ khóa mà không cần tháo rời, hỗ trợ người dùng tạo ra một bản sao chìa khóa tương ứng.</p>','<p>A keyhole-scanning system using ultrasound technology designed to decode most current mechanical locks. Using ultrasound technology, the system scans and reconstructs the internal mechanism of a lock in detail without disassembly, helping the user produce a corresponding duplicate key.</p>','published',0,11,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(37,12,'Hệ thống thu thập thông tin, định vị thuê bao di động 2G/3G/4G/5G đặt trên ô tô','Vehicle-Mounted 2G/3G/4G/5G Mobile Subscriber Detection & Locating System','he-thong-thu-thap-thong-tin-dinh-vi-thue-bao-di-dong-2g3g4g5g-dat-tren-o-to','vehicle-mounted-2g3g4g5g-mobile-subscriber-detection-locating-system',NULL,'Dùng để thu thập số định danh (IMSI) của các thuê bao di động 2G, 3G, 4G, 5G trong phạm vi lên tới 250 m cũng như xác định chính xác vị trí của chúng.','Used to collect the identifiers (IMSI) of 2G, 3G, 4G and 5G mobile subscribers within a range of up to 250 m, as well as to precisely determine their location.','<p>Dùng để thu thập số định danh (IMSI) của các thuê bao di động 2G, 3G, 4G, 5G trong phạm vi lên tới 250 m cũng như xác định chính xác vị trí của chúng. Sử dụng công nghệ SDR tiên tiến, hoạt động với tất cả các chuẩn 2G, 3G, 4G, 5G của tất cả các nhà mạng tại Việt Nam. Công suất phát của trạm BTS có thể điều chỉnh linh hoạt theo yêu cầu nhiệm vụ. Hệ thống có khả năng kiểm tra sự hiện diện của mục tiêu, định hướng và tìm kiếm thuê bao quan tâm thông qua bộ định vị cầm tay.</p>','<p>Used to collect the identifiers (IMSI) of 2G, 3G, 4G and 5G mobile subscribers within a range of up to 250 m, as well as to precisely determine their location. Uses advanced SDR technology, enabling operation with all 2G/3G/4G/5G standards of every mobile network operator in Vietnam. The BTS transmit power can be flexibly adjusted according to mission requirements. The system can check for a target&#039;s presence, and direction-find and search for a subscriber of interest via a handheld locator. Communication-parameter setup is automatically optimized to maximize the number of subscribers captured, while using an LAC matching that of the genuine network operator to avoid detection.</p>','published',0,12,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(38,12,'Hệ thống định vị thuê bao di động 2G/3G/4G/5G mang theo người','Body-Worn 2G/3G/4G/5G Mobile Subscriber Locating System','he-thong-dinh-vi-thue-bao-di-dong-2g3g4g5g-mang-theo-nguoi','body-worn-2g3g4g5g-mobile-subscriber-locating-system',NULL,'Dùng để thu thập số định danh (IMSI) của các thuê bao di động 2G, 3G, 4G, 5G trong phạm vi lên tới 50 m cũng như xác định chính xác vị trí của chúng.','Used to collect the identifiers (IMSI) of 2G, 3G, 4G and 5G mobile subscribers within a range of up to 50 m, as well as to precisely determine their location.','<p>Dùng để thu thập số định danh (IMSI) của các thuê bao di động 2G, 3G, 4G, 5G trong phạm vi lên tới 50 m cũng như xác định chính xác vị trí của chúng. Sử dụng công nghệ SDR tiên tiến, hoạt động với tất cả các chuẩn 2G, 3G, 4G, 5G của tất cả các nhà mạng tại Việt Nam. Công suất phát nhỏ, trọng lượng nhẹ phù hợp tiếp cận những tòa nhà cao tầng, những ngõ nhỏ ô tô không thể vào được.</p>','<p>Used to collect the identifiers (IMSI) of 2G, 3G, 4G and 5G mobile subscribers within a range of up to 50 m, as well as to precisely determine their location. Uses advanced SDR technology, enabling operation with all 2G/3G/4G/5G standards of every mobile network operator in Vietnam. Its low transmit power and light weight make it suitable for use in high-rise buildings and narrow alleys inaccessible to a vehicle.</p>','published',0,13,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(39,12,'Hệ thống khoanh vùng thuê bao di động','Mobile Subscriber Geolocation System','he-thong-khoanh-vung-thue-bao-di-dong','mobile-subscriber-geolocation-system',NULL,'Dùng để khoanh vùng, xác định vị trí và theo dõi, truy vết thuê bao di động 2G, 3G, 4G, 5G nhờ kết nối vào hệ thống báo hiệu của nhà mạng.','Used to geolocate, determine the position of, and track 2G, 3G, 4G and 5G mobile subscribers by connecting to the mobile network operator\'s signaling system.','<p>Dùng để khoanh vùng, xác định vị trí và theo dõi, truy vết thuê bao di động 2G, 3G, 4G, 5G nhờ kết nối vào hệ thống báo hiệu của nhà mạng. Thiết bị hỗ trợ giám sát các thuê bao nội địa, thuê bao quốc tế roaming vào Việt Nam, cũng như thuê bao trong nước di chuyển ra nước ngoài. Dữ liệu đầu vào là số IMSI hoặc MSISDN; kết quả trả về bao gồm vị trí, tọa độ chính xác của thuê bao dưới dạng đồ họa trực quan.</p>','<p>Used to geolocate, determine the position of, and track 2G, 3G, 4G and 5G mobile subscribers by connecting to the mobile network operator&#039;s signaling system. The device supports monitoring of domestic subscribers, international subscribers roaming into Vietnam, and domestic subscribers traveling abroad. Input data is an IMSI or MSISDN number; the returned results include the subscriber&#039;s precise position and coordinates presented in visual, graphical form.</p>','published',0,14,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:42',NULL),(40,12,'Hệ thống phân tích list liên lạc hình thành sơ đồ đường dây đối tượng','Call-Record Link Analysis & Association-Chart System','he-thong-phan-tich-list-lien-lac-hinh-thanh-so-do-duong-day-doi-tuong','call-record-link-analysis-association-chart-system',NULL,'Hệ thống được thiết kế nhằm hỗ trợ phân tích dữ liệu thu thập được trong quá trình điều tra và tìm kiếm, giúp người vận hành hình dung rõ ràng và toàn diện các mối quan hệ giữa các chủ thể liên quan.','A system designed to support analysis of data gathered during an investigation and search, helping the operator gain a clear, comprehensive picture of the relationships between the parties involved.','<p>Hệ thống được thiết kế nhằm hỗ trợ phân tích dữ liệu thu thập được trong quá trình điều tra và tìm kiếm, giúp người vận hành hình dung rõ ràng và toàn diện các mối quan hệ giữa các chủ thể liên quan. Dữ liệu đầu vào bao gồm các bản ghi chi tiết cuộc gọi (CDR) và bản ghi chi tiết sử dụng dịch vụ dựa trên giao thức Internet (IPDR). Thông qua các công cụ phân tích trực quan, hệ thống trình bày kết quả dưới dạng lược đồ kết nối, biểu đồ thời gian và các định dạng đồ họa khác.</p>','<p>A system designed to support analysis of data gathered during an investigation and search, helping the operator gain a clear, comprehensive picture of the relationships between the parties involved. Input data includes Call Detail Records (CDR) and Internet Protocol Detail Records (IPDR). Through visual analysis tools, the system presents results as connection diagrams, timelines and other graphical formats.</p>','published',0,15,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(41,12,'Hệ thống ghi âm, thu thập và phân tích dữ liệu âm thanh','Audio Recording, Collection & Analysis System','he-thong-ghi-am-thu-thap-va-phan-tich-du-lieu-am-thanh','audio-recording-collection-analysis-system',NULL,'Hệ thống được sử dụng để thu thập, ghi âm, lưu trữ và quản lý dữ liệu âm thanh từ nhiều nguồn tín hiệu khác nhau như microphone, đường dây điện thoại và các nguồn âm thanh tương tự.','A system used to collect, record, store and manage audio data from a variety of signal sources such as microphones, telephone lines and similar audio sources.','<p>Hệ thống được sử dụng để thu thập, ghi âm, lưu trữ và quản lý dữ liệu âm thanh từ nhiều nguồn tín hiệu khác nhau như microphone, đường dây điện thoại và các nguồn âm thanh tương tự. Thiết bị hỗ trợ ghi âm đồng thời nhiều kênh, giám sát hoạt động tín hiệu theo thời gian thực, lưu trữ dữ liệu dài hạn và cung cấp các công cụ tìm kiếm, phát lại, đánh dấu, phân loại và quản lý dữ liệu thông qua giao diện web bảo mật. Hệ thống đáp ứng yêu cầu phục vụ nhận dạng giọng nói, nhận dạng người nói và các hoạt động phân tích âm thanh chuyên sâu.</p>','<p>A system used to collect, record, store and manage audio data from a variety of signal sources such as microphones, telephone lines and similar audio sources. The device supports simultaneous multi-channel recording, real-time signal-activity monitoring, long-term data storage, and provides tools for searching, playback, tagging, categorization and data management through a secure web interface. The system meets the requirements for voice recognition, speaker identification and other in-depth audio analysis tasks.</p>','published',0,16,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(42,13,'Súng chế áp Drone','Drone Suppression Gun','sung-che-ap-drone','drone-suppression-gun',NULL,'Được thiết kế để phát hiện, định hướng và chế áp các loại drone bằng cách gây nhiễu các kênh điều khiển, truyền dữ liệu và tín hiệu định vị vệ tinh.','Designed to detect, direction-find and suppress drones by jamming their control, data-link and satellite-positioning signals.','<p>Được thiết kế để phát hiện, định hướng và chế áp các loại drone bằng cách gây nhiễu các kênh điều khiển, truyền dữ liệu và tín hiệu định vị vệ tinh. Có thể hoạt động độc lập, thích hợp cho các lực lượng an ninh, quân đội sử dụng trong bảo vệ khu vực nhạy cảm, chống do thám, chống khủng bố và bảo vệ sự kiện quan trọng.</p>','<p>Designed to detect, direction-find and suppress drones by jamming their control, data-link and satellite-positioning signals. Capable of standalone operation, suited to security and military forces for protecting sensitive areas, counter-surveillance, counter-terrorism and protection of major events.</p>','published',0,0,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(43,13,'Hệ thống phát hiện, chế áp UAV','UAV Detection & Suppression System','he-thong-phat-hien-che-ap-uav','uav-detection-suppression-system',NULL,'Hệ thống tác chiến điện tử đa năng, có khả năng phát hiện, định hướng, định vị và gây nhiễu các liên kết điều khiển, truyền dữ liệu và hệ thống định vị vệ tinh (GPS, GLONASS, BeiDou, Galileo) của UAV.','A multi-function electronic-warfare system capable of detecting, direction-finding, locating and jamming the control links, data links and satellite-navigation systems (GPS, GLONASS, BeiDou, Galileo) of UAVs.','<p>Hệ thống tác chiến điện tử đa năng, có khả năng phát hiện, định hướng, định vị và gây nhiễu các liên kết điều khiển, truyền dữ liệu và hệ thống định vị vệ tinh (GPS, GLONASS, BeiDou, Galileo) của UAV. Hỗ trợ nhiều chế độ hoạt động, có thể triển khai cố định hoặc cơ động trên xe quân sự. Có khả năng giả mạo tín hiệu định vị để điều khiển UAV bay lệch hướng và rơi tại khu vực được chỉ định; hiển thị vị trí của UAV và các trạm điều khiển mặt đất trên bản đồ số; giám sát và theo dõi UAV ở khoảng cách gần sử dụng mô-đun quang điện tử.</p>','<p>A multi-function electronic-warfare system capable of detecting, direction-finding, locating and jamming the control links, data links and satellite-navigation systems (GPS, GLONASS, BeiDou, Galileo) of UAVs. Supports multiple operating modes and can be deployed in a fixed installation or mounted on a military vehicle for mobile use, effectively serving security, defense, counter-terrorism and target-protection missions. Capable of spoofing positioning signals to force a UAV off course and cause it to land at a designated area; displays the position of the UAV and its ground control stations on a digital map; monitors and tracks a UAV at close range using an electro-optical module.</p>','published',0,1,NULL,NULL,'2026-08-21 00:18:18',NULL,1,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(44,13,'Đèn chiếu xa công suất cao có bộ lọc hồng ngoại','High-Power Long-Range Illuminator with Infrared Filter','den-chieu-xa-cong-suat-cao-co-bo-loc-hong-ngoai','high-power-long-range-illuminator-with-infrared-filter',NULL,'Loại đèn chiếu cơ động, đa năng, được thiết kế để sử dụng hiệu quả trong nhiều tình huống tác chiến như chiếu sáng tầm xa, khống chế đối tượng, giải tán đám đông, hoạt động cứu hộ cứu nạn và tìm kiếm bí mật vào ban đêm.','A mobile, multi-purpose illuminator designed for effective use in a range of operational situations such as long-range illumination, subject control, crowd dispersal, search-and-rescue operations and covert night searches.','<p>Loại đèn chiếu cơ động, đa năng, được thiết kế để sử dụng hiệu quả trong nhiều tình huống tác chiến như chiếu sáng tầm xa, khống chế đối tượng, giải tán đám đông, hoạt động cứu hộ cứu nạn và tìm kiếm bí mật vào ban đêm. Với khả năng chiếu sáng ở khoảng cách xa và thời lượng pin kéo dài, thiết bị đáp ứng tốt yêu cầu sử dụng trong các nhiệm vụ chuyên biệt và khẩn cấp.</p>','<p>A mobile, multi-purpose illuminator designed for effective use in a range of operational situations such as long-range illumination, subject control, crowd dispersal, search-and-rescue operations and covert night searches. With long-range illumination capability and extended battery life, the device meets the demands of specialized and emergency operations.</p>','published',0,2,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(45,13,'Đèn laser khống chế đối tượng','Laser Dazzler for Subject Control','den-laser-khong-che-doi-tuong','laser-dazzler-for-subject-control',NULL,'Thiết bị đèn chiếu laser chuyên dụng phát ánh sáng đỏ, đạt tiêu chuẩn an toàn, không gây tử vong hay tổn thương vĩnh viễn cho mắt.','A dedicated laser illumination device emitting red light that meets safety standards, causing no fatality or permanent eye injury.','<p>Thiết bị đèn chiếu laser chuyên dụng phát ánh sáng đỏ, đạt tiêu chuẩn an toàn, không gây tử vong hay tổn thương vĩnh viễn cho mắt. Thiết bị có khả năng gây lóa tạm thời, làm giảm khả năng phản kháng của đối tượng trong phạm vi vài chục mét; đồng thời hỗ trợ tìm và truyền tín hiệu cảnh báo.</p>','<p>A dedicated laser illumination device emitting red light that meets safety standards, causing no fatality or permanent eye injury. The device can produce temporary dazzling to reduce a subject&#039;s ability to resist within a range of several dozen meters, and also supports search and transmission of a warning signal.</p>','published',0,3,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(46,13,'Khiên đa năng chống bạo động','Multi-Function Anti-Riot Shield','khien-da-nang-chong-bao-dong','multi-function-anti-riot-shield',NULL,'Khiên tay chống bạo động đa chức năng là thiết bị chuyên dụng hỗ trợ lực lượng chức năng trong các tình huống kiểm soát đám đông hoặc trấn áp đối tượng nguy hiểm.','A multi-function hand-held anti-riot shield is a dedicated device that supports law-enforcement forces in crowd-control situations or in subduing dangerous subjects.','<p>Khiên tay chống bạo động đa chức năng là thiết bị chuyên dụng hỗ trợ lực lượng chức năng trong các tình huống kiểm soát đám đông hoặc trấn áp đối tượng nguy hiểm. Khiên được tích hợp nhiều tiện ích như bình xịt cay, đèn chiếu sáng, còi báo động và bộ phận hỗ trợ phá cửa, giúp nâng cao hiệu quả tác chiến.</p>','<p>A multi-function hand-held anti-riot shield is a dedicated device that supports law-enforcement forces in crowd-control situations or in subduing dangerous subjects. The shield integrates several utilities such as a pepper-spray canister, illumination light, alarm siren and door-breaching aid, improving operational effectiveness.</p>','published',0,4,NULL,NULL,'2026-08-21 00:18:18',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(47,13,'Dùi cui','Baton','dui-cui','baton',NULL,'Dùi cui giúp ngăn chặn hoặc khống chế nhanh các hành vi bạo lực, chống đối mà không cần sử dụng vũ khí sát thương.','A baton helps quickly prevent or subdue violent or resistant behavior without the need for lethal weapons.','<p>Dùi cui giúp ngăn chặn hoặc khống chế nhanh các hành vi bạo lực, chống đối mà không cần sử dụng vũ khí sát thương.</p>','<p>A baton helps quickly prevent or subdue violent or resistant behavior without the need for lethal weapons.</p>','published',0,5,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-08-21 00:18:19',NULL),(48,13,'Còng tay','Handcuffs','cong-tay','handcuffs',NULL,'Còng tay giúp cố định tay của người bị bắt, hạn chế khả năng chống trả, tấn công hoặc bỏ trốn.','Handcuffs secure the hands of a detained person, restricting their ability to resist, attack or flee.','<p>Còng tay giúp cố định tay của người bị bắt, hạn chế khả năng chống trả, tấn công hoặc bỏ trốn.</p>','<p>Handcuffs secure the hands of a detained person, restricting their ability to resist, attack or flee.</p>','published',0,6,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-08-21 00:18:19',NULL),(49,14,'Hệ thống quét 3D laser cầm tay','Handheld 3D Laser Scanning System','he-thong-quet-3d-laser-cam-tay','handheld-3d-laser-scanning-system',NULL,'Hệ thống quét 3D chuyên dụng dùng để tạo bản vẽ 3D chi tiết của các bộ phận hoặc sản phẩm một cách chính xác.','A dedicated 3D scanning system used to accurately create detailed 3D drawings of parts or products.','<p>Hệ thống quét 3D chuyên dụng dùng để tạo bản vẽ 3D chi tiết của các bộ phận hoặc sản phẩm một cách chính xác. Với tính cơ động và linh hoạt cao, hệ thống có thể triển khai trong điều kiện không gian hạn chế. Hỗ trợ quét từ vật thể nhỏ đến lớn mà không giới hạn kích thước, đồng thời xử lý hiệu quả các bề mặt phức tạp như inox, đen bóng mà không cần xịt bột, kể cả trong điều kiện máy và vật thể cùng di chuyển.</p>','<p>A dedicated 3D scanning system used to accurately create detailed 3D drawings of parts or products. With high mobility and flexibility, the system can be deployed in confined spaces. It supports scanning objects from small to large without size restriction, and effectively handles complex surfaces such as stainless steel or glossy black finishes without the need for scanning spray, even while the scanner and the object are both in motion.</p>','published',0,0,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(50,14,'Hệ thống in 3D kim loại','Metal 3D Printing System','he-thong-in-3d-kim-loai','metal-3d-printing-system',NULL,'Hệ thống in 3D công suất cao được thiết kế nhỏ gọn, chính xác, phù hợp cho nhiều ứng dụng từ tạo mẫu nhanh, sản xuất khối lượng thấp đến sản xuất hàng loạt và nghiên cứu chuyên sâu.','A high-power 3D printing system with a compact, precise design, suited to a range of applications from rapid prototyping and low-volume production to mass production and in-depth research.','<p>Hệ thống in 3D công suất cao được thiết kế nhỏ gọn, chính xác, phù hợp cho nhiều ứng dụng từ tạo mẫu nhanh, sản xuất khối lượng thấp đến sản xuất hàng loạt và nghiên cứu chuyên sâu. Thiết bị hỗ trợ in với dải vật liệu đa dạng như thép, titan, niken, đồng, nhôm..., đáp ứng linh hoạt yêu cầu kỹ thuật trong các lĩnh vực công nghiệp và khoa học công nghệ.</p>','<p>A high-power 3D printing system with a compact, precise design, suited to a range of applications from rapid prototyping and low-volume production to mass production and in-depth research. The device supports printing with a diverse range of materials such as steel, titanium, nickel, copper and aluminum, flexibly meeting technical requirements across industrial and technology sectors.</p>','published',0,1,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(51,14,'Hệ thống in 3D nhựa công nghệ FDM','FDM Plastic 3D Printing System','he-thong-in-3d-nhua-cong-nghe-fdm','fdm-plastic-3d-printing-system',NULL,'Giải pháp tối ưu, kết hợp giữa chất lượng in cao và khả năng sản xuất các chi tiết có kích thước lớn.','An optimal solution combining high print quality with the ability to produce large-sized parts.','<p>Giải pháp tối ưu, kết hợp giữa chất lượng in cao và khả năng sản xuất các chi tiết có kích thước lớn. Hệ thống hỗ trợ in nhiều loại vật liệu khác nhau, cho phép tạo ra các chi tiết phức tạp với độ chính xác cao. Thiết lập hệ thống đơn giản, dễ vận hành mà không cần đào tạo chuyên sâu, phù hợp với nhiều ứng dụng.</p>','<p>An optimal solution combining high print quality with the ability to produce large-sized parts. The system supports printing a variety of materials, enabling the creation of complex parts with high precision. Setup is simple and easy to operate without extensive training, suited to a wide range of applications.</p>','published',0,2,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(52,15,'Kính hiển vi soi nổi 3D độ phân giải 6K','6K-Resolution 3D Stereo Microscope','kinh-hien-vi-soi-noi-3d-do-phan-giai-6k','6k-resolution-3d-stereo-microscope',NULL,'Kính hiển vi kỹ thuật số 3D soi nổi đầu tiên trên thế giới được trang bị camera độ phân giải 6K cùng trường nhìn rộng, mang đến khả năng tái hiện hình ảnh nổi khối chính xác, hỗ trợ hiệu quả cho các giám định viên trong quá trình phân tích, đo đạc mẫu vật và nhận diện dấu vết giả như con dấu, tài liệu nghi vấn.','The world\'s first digital 3D stereo microscope equipped with a 6K-resolution camera and a wide field of view, delivering accurate stereoscopic image reproduction that effectively supports examiners in analyzing, measuring specimens and identifying forged traces such as seals or questioned documents.','<p>Kính hiển vi kỹ thuật số 3D soi nổi đầu tiên trên thế giới được trang bị camera độ phân giải 6K cùng trường nhìn rộng, mang đến khả năng tái hiện hình ảnh nổi khối chính xác, hỗ trợ hiệu quả cho các giám định viên trong quá trình phân tích, đo đạc mẫu vật và nhận diện dấu vết giả như con dấu, tài liệu nghi vấn. Thiết bị tích hợp đa dạng hệ thống chiếu sáng và cho phép xuất báo cáo trực tiếp dưới các định dạng phổ biến như Excel, Word, PDF…</p>','<p>The world&#039;s first digital 3D stereo microscope equipped with a 6K-resolution camera and a wide field of view, delivering accurate stereoscopic image reproduction that effectively supports examiners in analyzing, measuring specimens and identifying forged traces such as seals or questioned documents. The device integrates a range of lighting systems, flexibly meeting different observation conditions. With multiple observation and imaging modes, this microscope is widely used across many scientific and technical fields. The system can also export reports directly in common formats such as Excel, Word and PDF.</p>','published',0,0,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:42',NULL),(53,15,'Hệ thống quét 3D dựng và phân tích hiện trường','3D Crime-Scene Scanning & Reconstruction System','he-thong-quet-3d-dung-va-phan-tich-hien-truong','3d-crime-scene-scanning-reconstruction-system',NULL,'Hệ thống cho phép ghi lại hình ảnh không gian ba chiều tại hiện trường một cách khách quan và chính xác, giúp tái hiện đầy đủ bối cảnh xảy ra vụ việc.','A system that captures three-dimensional imagery of a scene objectively and accurately, enabling full reconstruction of the context in which an event occurred.','<p>Hệ thống cho phép ghi lại hình ảnh không gian ba chiều tại hiện trường một cách khách quan và chính xác, giúp tái hiện đầy đủ bối cảnh xảy ra vụ việc. Dữ liệu 3D thu thập được hỗ trợ cơ quan chức năng trong việc phân tích, đánh giá hiện trường sau khám nghiệm mà không cần quay lại thực địa. Hệ thống có khả năng lưu giữ trung thực các dấu vết &quot;nóng&quot; dễ bị biến đổi do điều kiện thời tiết hoặc tự tiêu hủy theo thời gian.</p>','<p>A system that captures three-dimensional imagery of a scene objectively and accurately, enabling full reconstruction of the context in which an event occurred. The captured 3D data helps authorities analyze and assess the scene after the on-site examination without needing to return to the physical location. Notably, the system can faithfully preserve &quot;hot&quot; traces that are prone to change due to weather conditions or that self-degrade over time.</p>','published',0,1,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(54,15,'Hệ thống phòng Lab phục hồi, trích xuất dữ liệu kỹ thuật số điện tử','Digital Forensic Data Recovery & Extraction Lab System','he-thong-phong-lab-phuc-hoi-trich-xuat-du-lieu-ky-thuat-so-dien-tu','digital-forensic-data-recovery-extraction-lab-system',NULL,'Hệ thống phòng Lab phục hồi và trích xuất dữ liệu kỹ thuật số – điện từ được thiết kế chuyên biệt, tích hợp đầy đủ trang thiết bị phần cứng, công cụ và phần mềm chuyên dụng nhằm hỗ trợ tối đa cho các chuyên gia trong công tác thu thập và khôi phục dữ liệu.','A dedicated digital/electronic forensic data-recovery and extraction laboratory system, fully integrating the hardware, tools and dedicated software needed to give maximum support to specialists in data collection and recovery.','<p>Hệ thống phòng Lab phục hồi và trích xuất dữ liệu kỹ thuật số – điện từ được thiết kế chuyên biệt, tích hợp đầy đủ trang thiết bị phần cứng, công cụ và phần mềm chuyên dụng nhằm hỗ trợ tối đa cho các chuyên gia trong công tác thu thập và khôi phục dữ liệu. Hệ thống cho phép xử lý hiệu quả dữ liệu từ nhiều loại phương tiện kỹ thuật số khác nhau, bao gồm ổ cứng HDD/SSD, điện thoại di động, thẻ nhớ Flash, thiết bị lưu trữ NAND và đầu ghi hình DVR-CCTV…</p>','<p>A dedicated digital/electronic forensic data-recovery and extraction laboratory system, fully integrating the hardware, tools and dedicated software needed to give maximum support to specialists in data collection and recovery. The system can efficiently process data from a wide range of digital media, including HDD/SSD drives, mobile phones, Flash memory cards, NAND storage devices and DVR/CCTV recorders. With the ability to recover data in complex scenarios, including from damaged devices, this laboratory system is an indispensable tool for digital investigation, electronic forensic examination and in-depth digital-data analysis.</p>','published',0,2,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(55,15,'Dây chuyền lắp ráp bảng mạch điện tử SMT tự động','Automated SMT Electronic Board Assembly Line','day-chuyen-lap-rap-bang-mach-dien-tu-smt-tu-dong','automated-smt-electronic-board-assembly-line',NULL,'Dây chuyền lắp ráp bảng mạch điện tử SMT tự động được thiết kế đồng bộ, hiện đại, đáp ứng các yêu cầu sản xuất linh kiện điện tử chính xác cao.','An automated SMT (surface-mount technology) electronic board assembly line, designed as a modern, synchronized production line, meeting the requirements for high-precision electronic component manufacturing.','<p>Dây chuyền lắp ráp bảng mạch điện tử SMT tự động được thiết kế đồng bộ, hiện đại, đáp ứng các yêu cầu sản xuất linh kiện điện tử chính xác cao. Dây chuyền gồm đầy đủ các thiết bị hiện đại như: máy in kem thiếc, máy kiểm tra kem hàn (SPI), máy gắn linh kiện, lò hàn đối lưu và thiết bị đo nhiệt độ lò. Sau hàn, mạch được kiểm tra bằng máy AOI tự động.</p>','<p>An automated SMT (surface-mount technology) electronic board assembly line, designed as a modern, synchronized production line, meeting the requirements for high-precision electronic component manufacturing. The line includes a full set of modern equipment such as a solder-paste printer, a Solder Paste Inspection (SPI) machine, a component placement machine, a reflow oven and an oven-temperature measurement device. After soldering, boards are inspected by an automated AOI machine. The entire process is supported by a board-feeding/unloading system and conveyor, ensuring fast, precise production, reduced defects and increased throughput.</p>','published',0,3,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(56,15,'Hệ thống camera giám sát an ninh','Security Camera Surveillance System','he-thong-camera-giam-sat-an-ninh','security-camera-surveillance-system',NULL,'Hệ thống camera giám sát an ninh là giải pháp công nghệ hiện đại được sử dụng rộng rãi nhằm đảm bảo an toàn cho khu vực cần được bảo vệ.','A security camera surveillance system is a modern technology solution widely used to ensure the safety of an area requiring protection.','<p>Hệ thống camera giám sát an ninh là giải pháp công nghệ hiện đại được sử dụng rộng rãi nhằm đảm bảo an toàn cho khu vực cần được bảo vệ. Hệ thống bao gồm các camera quan sát được lắp đặt tại các vị trí trọng yếu, kết hợp với thiết bị ghi hình và phần mềm quản lý, cho phép theo dõi, ghi lại và lưu trữ hình ảnh, video trong thời gian thực. Nhờ khả năng hoạt động liên tục 24/7 và hỗ trợ giám sát từ xa qua mạng internet, hệ thống camera giúp phát hiện sớm các hành vi xâm nhập, trộm cắp hoặc sự cố bất thường.</p>','<p>A security camera surveillance system is a modern technology solution widely used to ensure the safety of an area requiring protection. The system comprises observation cameras installed at key locations, combined with recording devices and management software, enabling real-time monitoring, recording and storage of images and video. With the ability to operate continuously 24/7 and support remote monitoring over the internet, the camera system helps detect intrusion, theft or unusual incidents early, contributing to more effective management, prevention and timely handling of security situations.</p>','published',0,4,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(57,15,'Hệ thống phát hiện đột nhập không dây','Wireless Intrusion Detection System','he-thong-phat-hien-dot-nhap-khong-day','wireless-intrusion-detection-system',NULL,'Giải pháp giám sát tự động, hoạt động độc lập, sử dụng các loại cảm biến như địa chấn, hồng ngoại, vi sóng để phát hiện đối tượng xâm nhập.','An automated, standalone surveillance solution using sensors such as seismic, infrared and microwave sensors to detect intruding subjects.','<p>Giải pháp giám sát tự động, hoạt động độc lập, sử dụng các loại cảm biến như địa chấn, hồng ngoại, vi sóng để phát hiện đối tượng xâm nhập. Hệ thống được tích hợp với camera cố định và UAV nhằm theo dõi, xác minh mục tiêu một cách chính xác và kịp thời. Cấu trúc hệ thống linh hoạt phù hợp với nhiều địa hình khác nhau, mọi thông tin từ cảm biến đều được gửi về trung tâm chỉ huy.</p>','<p>An automated, standalone surveillance solution using sensors such as seismic, infrared and microwave sensors to detect intruding subjects. The system integrates with fixed cameras and UAVs to track and verify a target accurately and promptly. Its flexible architecture suits a variety of terrain types, with all sensor information sent to a command center for comprehensive monitoring of the surveillance area.</p>','published',0,5,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(58,15,'Trường bắn mô phỏng','Simulated Training Range','truong-ban-mo-phong','simulated-training-range',NULL,'Giải pháp huấn luyện chiến thuật hiện đại ứng dụng công nghệ XR (VR, AR, MR) nhằm tạo ra môi trường chiến trường ảo siêu thực tế.','A modern tactical training solution applying XR technology (VR, AR, MR) to create an ultra-realistic virtual battlefield environment.','<p>Giải pháp huấn luyện chiến thuật hiện đại ứng dụng công nghệ XR (VR, AR, MR) nhằm tạo ra môi trường chiến trường ảo siêu thực tế. Hệ thống cho phép binh sĩ luyện tập kỹ năng chiến đấu, nâng cao khả năng ra quyết định và phối hợp nhóm trong các tình huống áp lực cao. Với các mô phỏng đa dạng như đô thị, hẻm nhỏ, tòa nhà hay trung tâm thương mại, học viên có thể huấn luyện sát thực tế mà không cần sử dụng đạn thật. Vũ khí mô phỏng có trọng lượng, độ giật và thao tác như thật.</p>','<p>A modern tactical training solution applying XR technology (VR, AR, MR) to create an ultra-realistic virtual battlefield environment. The system lets personnel practice combat skills and improve decision-making and team coordination under high-pressure situations. With diverse simulated scenarios such as urban settings, narrow alleys, buildings and shopping centers, trainees can train under realistic conditions without using live ammunition, reducing risk. Simulated weapons replicate real weight, recoil and handling, helping build muscle memory.</p>','published',0,6,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(59,15,'Hệ thống mô phỏng bắn lái xe tăng','Tank Driving & Gunnery Simulator System','he-thong-mo-phong-ban-lai-xe-tang','tank-driving-gunnery-simulator-system',NULL,'Hệ thống mô phỏng được thiết kế nhằm đáp ứng yêu cầu giảng dạy và huấn luyện tổng hợp cho kíp xe tăng, phục vụ mục đích phối hợp tác chiến trong các nhiệm vụ bắn, lái xe và triển khai chiến thuật trên địa hình mặt đất, phù hợp với nhiều điều kiện hoạt động khác nhau.','A simulator system designed to meet the teaching and integrated training requirements of a tank crew, serving combined-arms coordination in gunnery, driving and tactical deployment tasks on varied terrain and operating conditions.','<p>Hệ thống mô phỏng được thiết kế nhằm đáp ứng yêu cầu giảng dạy và huấn luyện tổng hợp cho kíp xe tăng, phục vụ mục đích phối hợp tác chiến trong các nhiệm vụ bắn, lái xe và triển khai chiến thuật trên địa hình mặt đất, phù hợp với nhiều điều kiện hoạt động khác nhau.</p>','<p>A simulator system designed to meet the teaching and integrated training requirements of a tank crew, serving combined-arms coordination in gunnery, driving and tactical deployment tasks on varied terrain and operating conditions.</p>','published',0,7,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(60,15,'Hệ thống trinh sát thông tin nguồn mở (OSINT)','Open-Source Intelligence (OSINT) Reconnaissance System','he-thong-trinh-sat-thong-tin-nguon-mo-osint','open-source-intelligence-osint-reconnaissance-system',NULL,'Hệ thống OSINT (Open Source Intelligence) là công cụ thu thập, xử lý và phân tích dữ liệu từ các nguồn công khai nhằm hỗ trợ tình báo, giám sát, và ra quyết định — nền tảng trọng yếu trong giám sát không gian mạng, đảm bảo an ninh quốc gia và ổn định xã hội.','An OSINT (Open Source Intelligence) system is a tool for collecting, processing and analyzing data from public sources to support intelligence, surveillance and decision-making.','<p>Hệ thống OSINT (Open Source Intelligence) là công cụ thu thập, xử lý và phân tích dữ liệu từ các nguồn công khai nhằm hỗ trợ tình báo, giám sát, và ra quyết định — nền tảng trọng yếu trong giám sát không gian mạng, đảm bảo an ninh quốc gia và ổn định xã hội. Chức năng chính: thu thập dữ liệu từ mạng xã hội, báo chí, website, diễn đàn, cơ sở dữ liệu công khai, dark web; lọc và chuẩn hóa dữ liệu; phân tích nội dung bằng NLP/AI để nhận diện chủ đề, thực thể, cảm xúc, mối liên hệ; giám sát thời gian thực; cảnh báo sớm nguy cơ khủng bố, tội phạm mạng, tin giả; trực quan hóa dữ liệu và xuất báo cáo tình báo.</p>','<p>An OSINT (Open Source Intelligence) system is a tool for collecting, processing and analyzing data from public sources to support intelligence, surveillance and decision-making. An OSINT system is a critical platform for cyberspace monitoring, national security and social stability. Key functions: collecting data from social media, press, websites, forums, public databases and the dark web; filtering and normalizing data, removing noise, duplicate or irrelevant data; content analysis using NLP/AI to identify topics, entities, sentiment and relationships; real-time monitoring; early warning of terrorism, cybercrime and disinformation risks; data visualization; and export of intelligence reports.</p>','published',0,8,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL),(61,15,'Hệ thống giám sát vệ tinh bằng phương tiện bay không người lái','UAV-Based Satellite Uplink Monitoring System','he-thong-giam-sat-ve-tinh-bang-phuong-tien-bay-khong-nguoi-lai','uav-based-satellite-uplink-monitoring-system',NULL,'Hệ thống giám sát vệ tinh sử dụng nền tảng bay không người lái cho phép phát hiện, định vị và theo dõi hoạt động của các trạm phát vệ tinh mặt đất.','A satellite-monitoring system using an unmanned aerial platform to detect, locate and track the activity of ground satellite-transmission stations.','<p>Hệ thống giám sát vệ tinh sử dụng nền tảng bay không người lái cho phép phát hiện, định vị và theo dõi hoạt động của các trạm phát vệ tinh mặt đất. Thiết bị thu thập dữ liệu vô tuyến và tín hiệu telemetry, hoạt động ở chế độ thụ động hoặc bán chủ động. Hệ thống tích hợp camera quang học – nhiệt giúp quan sát đồng thời hình ảnh thực địa. Dữ liệu được xử lý để tạo bản đồ nhiệt 4D, phục vụ giám sát phổ tần và phân tích chiến thuật.</p>','<p>A satellite-monitoring system using an unmanned aerial platform to detect, locate and track the activity of ground satellite-transmission stations. The device collects radio-frequency data and telemetry signals, operating in a passive or semi-active mode. The system integrates an optical-thermal camera for simultaneous real-world imaging. Data is processed to produce a 4D heat map, supporting spectrum monitoring and tactical analysis.</p>','published',0,9,NULL,NULL,'2026-08-21 00:18:19',NULL,NULL,'2026-08-20 20:47:09','2026-09-08 00:28:08',NULL);
