INSERT INTO `settings` VALUES (1,'company_name','CÔNG TY CỔ PHẦN THIẾT BỊ CÔNG NGHIỆP VÀ CHUYỂN GIAO CÔNG NGHỆ VIỆT THẮNG','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(2,'company_name_intl','VIET THANG INDUSTRIAL EQUIPMENT AND TECHNOLOGY TRANSFER JOINT STOCK COMPANY','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(3,'company_short_name','VIETTC., JSC','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(4,'founded_year','2003','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(5,'charter_capital','200.000.000.000 VNĐ','string','2026-08-20 19:57:05','2026-08-28 21:41:52'),(6,'employee_count','100+','string','2026-08-20 19:57:05','2026-08-28 21:41:52'),(7,'partner_count','300+','string','2026-08-20 19:57:05','2026-08-28 21:41:52'),(8,'ceo_name','Phí Bá Linh','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(9,'headquarters_address','Số 19, ngõ 159 Pháo Đài Láng, phường Láng, Hà Nội','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(10,'office_address','Tầng 8, tòa nhà Diamond Flower (Handico 6), đường Lê Văn Lương, phường Thanh Xuân, Hà Nội','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(11,'phone','024.66665511 / 024.66665522','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(12,'fax','024.66665577','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(13,'email','info@vietthang.vn','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(14,'website','https://www.vietthang.vn','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(15,'logo_path','settings/01M1QSJ5ND9KBJXS8XRPGZYTSZ.png','string','2026-08-20 19:57:05','2026-09-04 20:24:58'),(16,'hero_headline','CÔNG NGHỆ TIÊN TIẾN. GIẢI PHÁP TIN CẬY.','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(17,'hero_subheadline','Cung cấp các giải pháp và thiết bị công nghệ cao cho an ninh, quốc phòng và hạ tầng trọng yếu.','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(18,'about_summary','Công ty Cổ phần Thiết bị Công nghiệp và Chuyển giao Công nghệ Việt Thắng (VIETTC., JSC) thành lập năm 2003, là nhà nhập khẩu, phân phối độc quyền và nhà sản xuất các trang thiết bị nghiệp vụ đặc biệt phục vụ an ninh - quốc phòng tại Việt Nam.','string','2026-08-20 19:57:05','2026-08-20 19:57:05'),(19,'hero_headline_en','ADVANCED TECHNOLOGY. TRUSTED SOLUTIONS.','string','2026-08-21 00:18:18','2026-08-21 00:18:18'),(20,'hero_subheadline_en','Providing high-technology solutions and equipment for security, defense and critical infrastructure.','string','2026-08-21 00:18:18','2026-08-21 00:18:18'),(21,'about_summary_en','Viet Thang Industrial Equipment and Technology Transfer Joint Stock Company (VIETTC., JSC), founded in 2003, is an importer, exclusive distributor and manufacturer of specialized equipment for the security and defense sector in Vietnam.','string','2026-08-21 00:18:18','2026-08-21 00:18:18'),(51,'about_content','VIETTC., JSC – HƠN 20 NĂM KIẾN TẠO GIẢI PHÁP CÔNG NGHỆ CHUYÊN DỤNG\n\nCông ty Cổ phần Thiết bị Công nghiệp và Chuyển giao Công nghệ Việt Thắng (VIETTC., JSC) được thành lập từ năm 2003, là doanh nghiệp hoạt động chuyên sâu trong lĩnh vực thiết bị an ninh – quốc phòng, công nghệ chuyên dụng, điện tử viễn thông và chuyển giao công nghệ. Trải qua hơn 20 năm xây dựng và phát triển, VIETTC., JSC từng bước khẳng định năng lực, uy tín và vị thế là một trong những đơn vị cung cấp thiết bị, công nghệ và giải pháp chuyên dụng cho các cơ quan, đơn vị trong nước.\n\nKhông chỉ dừng lại ở vai trò nhập khẩu và phân phối thiết bị, VIETTC., JSC định hướng phát triển theo mô hình tích hợp công nghệ và cung cấp giải pháp toàn diện. Công ty có năng lực nghiên cứu, tư vấn, chuyển giao công nghệ, nghiên cứu chế tạo và sản xuất một số trang thiết bị nghiệp vụ đặc biệt, đồng thời triển khai các dịch vụ lắp đặt, bảo hành, bảo trì và hỗ trợ kỹ thuật sau bán hàng.\n\nNăng lực công nghệ – nền tảng tạo nên khác biệt\n\nVIETTC., JSC sở hữu đội ngũ hơn 100 cán bộ, nhân viên, trong đó có các chuyên gia trình độ tiến sĩ, thạc sĩ, kỹ sư và cử nhân, cùng lực lượng kỹ thuật chuyên trách triển khai, lắp đặt và thi công dự án. Phòng Kỹ thuật & Giải pháp đảm nhiệm nghiên cứu, đánh giá thiết bị, phối hợp với các viện nghiên cứu và các nhà sản xuất quốc tế để tiếp nhận, chuyển giao và phát triển những giải pháp công nghệ tiên tiến.\n\nCác lĩnh vực chuyên môn của VIETTC., JSC bao gồm hệ thống camera giám sát thông minh (CCTV), hệ thống xử lý kỹ thuật tài liệu chuyên dụng, thiết bị phát hiện và tìm kiếm, thiết bị phòng chống cháy nổ và phát hiện vật liệu cất giấu, thiết bị phục vụ giám định, cùng các công nghệ và dây chuyền sản xuất thiết bị nghiệp vụ đặc biệt.\n\nKết nối công nghệ toàn cầu – phục vụ nhu cầu trong nước\n\nVới mạng lưới quan hệ được xây dựng qua nhiều năm, VIETTC., JSC hợp tác với các viện nghiên cứu, nhà khoa học, nhà máy và các tập đoàn, nhà sản xuất công nghệ trên thế giới trong hoạt động nghiên cứu, chuyển giao công nghệ, sản xuất và cung cấp thiết bị. Hồ sơ năng lực ghi nhận quan hệ phân phối với nhiều thương hiệu quốc tế trong các lĩnh vực như quét dựng hiện trường 3D, phát hiện ma túy – chất nổ – hóa chất, camera an ninh, công nghệ RF, kính hiển vi, soi chiếu, phát hiện phóng xạ, sinh trắc học, nhận dạng khuôn mặt, xử lý âm thanh và hình ảnh.\n\nNăng lực được kiểm chứng bằng những dự án thực tế\n\nNăng lực của VIETTC., JSC được thể hiện qua quá trình triển khai các dự án có quy mô lớn trong lĩnh vực công nghệ chuyên dụng. \n\nVới năng lực từ nghiên cứu – tư vấn – cung cấp – tích hợp – chuyển giao công nghệ – triển khai – bảo hành và bảo trì, VIETTC., JSC hướng tới trở thành đối tác công nghệ tin cậy, đồng hành cùng khách hàng trong việc tiếp cận những công nghệ tiên tiến và xây dựng các giải pháp chuyên dụng có tính thực tiễn, hiệu quả và lâu dài.\n\nVIETTC., JSC – Khẳng định uy tín vượt trội.\nKết nối công nghệ tiên tiến – Kiến tạo giải pháp chuyên dụng – Đồng hành cùng khách hàng.','string','2026-09-04 19:06:50','2026-09-06 21:42:15'),(52,'about_content_en','VIETTC., JSC – OVER 20 YEARS OF BUILDING ADVANCED TECHNOLOGY SOLUTIONS\n\nViet Thang Industrial Equipment and Technology Transfer Joint Stock Company (VIETTC., JSC) is a Vietnamese company with more than 20 years of experience in security and defense equipment, specialized technologies, telecommunications and technology transfer. Established in 2003, VIETTC., JSC has continuously developed its capabilities and established a strong reputation as a trusted provider of specialized equipment, advanced technologies and integrated solutions for organizations and agencies across Vietnam.\n\nFrom its origins as an importer and supplier of machinery, equipment and technologies for the security and defense sectors, VIETTC., JSC has evolved into a technology-driven solution provider with capabilities spanning technology consulting, equipment supply, technology transfer, research and development, product manufacturing, system deployment, installation, maintenance and after-sales technical support.\n\nTECHNOLOGY EXPERTISE & ENGINEERING CAPABILITIES\n\nOur strength lies in our professional engineering team and technical expertise. VIETTC., JSC currently has more than 100 employees, including PhD-level experts, master\'s degree holders, engineers and bachelor\'s degree professionals, together with dedicated personnel responsible for project installation and implementation.\n\nOur Technical & Solutions Division works closely with research institutes and leading international manufacturers to evaluate technologies, facilitate technology transfer and develop modern, practical and optimized solutions tailored to customer requirements.\n\nOur technology portfolio covers a wide range of specialized applications, including intelligent CCTV surveillance systems, specialized document processing systems, detection and search equipment, security screening solutions, fire and explosive safety equipment, concealed-material detection systems, forensic equipment and specialized operational technologies.\n\nGLOBAL TECHNOLOGY – LOCAL EXPERTISE\n\nOver more than two decades, VIETTC., JSC has established trusted relationships with research institutes, scientists, manufacturers and technology groups around the world, enabling us to continuously access and introduce advanced technologies to the Vietnamese market.\n\nOur international technology network covers solutions including 3D crime-scene scanning and reconstruction, narcotics and explosive detection, intelligent surveillance, RF-based security systems, microscopy, security screening, radiation detection, biometrics, facial recognition, audio and video processing and analysis, among other specialized technologies.\n\nPROVEN EXPERIENCE. TRUSTED CAPABILITY.\n\nOur capabilities are demonstrated through the successful implementation of major technology projects for Vietnamese public-sector organizations.\n\nBEYOND EQUIPMENT. WE DELIVER TECHNOLOGY.\n\nAt VIETTC., JSC, we believe that true value goes beyond supplying equipment. We provide technology, engineering expertise and complete solutions — from understanding customer requirements and selecting the right technology, to system integration, technology transfer, installation, commissioning, training, maintenance and long-term technical support.\n\nWith the guiding principle “Proving Outstanding Reputation,” VIETTC., JSC is committed to continuously strengthening its technological capabilities, expanding international cooperation and delivering reliable, innovative and high-performance solutions that create lasting value for our customers and partners.\n\nVIETTC., JSC\nConnecting Advanced Technology. Engineering Specialized Solutions. Building Trusted Partnerships.','string','2026-09-04 19:06:50','2026-09-06 21:42:15'),(54,'technology_content','<p></p><h2><img src=\"http://127.0.0.1:8000/storage/settings/technology/KdCOjQsHzI6zVAKhZSC1iauYvVHP2b7BfAIsc8c3.png\" data-id=\"settings/technology/KdCOjQsHzI6zVAKhZSC1iauYvVHP2b7BfAIsc8c3.png\"></h2><p></p><p>Tại <strong>VIETTC., JSC</strong>, công nghệ không chỉ là những thiết bị được cung cấp, mà là năng lực <strong>nghiên cứu, tích hợp, chuyển giao và ứng dụng công nghệ</strong> để giải quyết những yêu cầu chuyên biệt trong lĩnh vực an ninh, quốc phòng và các ngành công nghiệp công nghệ cao.</p><p>Với hơn <strong>20 năm kinh nghiệm</strong>, VIETTC., JSC đã xây dựng hệ sinh thái hợp tác với các <strong>viện nghiên cứu, chuyên gia, nhà sản xuất và tập đoàn công nghệ quốc tế</strong>, qua đó liên tục tiếp cận và đưa những công nghệ tiên tiến vào các giải pháp phục vụ khách hàng tại Việt Nam.</p><h3>Năng lực công nghệ toàn diện</h3><p>VIETTC., JSC sở hữu đội ngũ kỹ thuật và chuyên gia có nền tảng trong các lĩnh vực <strong>điện tử viễn thông, công nghệ thông tin và kỹ thuật chuyên dụng</strong>. Phòng Kỹ thuật &amp; Giải pháp đảm nhiệm việc nghiên cứu, đánh giá công nghệ, phối hợp với các đối tác trong và ngoài nước để lựa chọn, chuyển giao và phát triển những giải pháp phù hợp với yêu cầu thực tế.</p><p>Bên cạnh đó, năng lực <strong>nghiên cứu và chế tạo sản phẩm</strong> cho phép VIETTC., JSC chủ động tham gia vào quá trình phát triển các thiết bị phục vụ các dự án chuyên dụng, thay vì chỉ đóng vai trò đơn thuần là nhà cung cấp thiết bị.</p><h3>Các lĩnh vực công nghệ</h3><p>Hệ thống năng lực công nghệ của VIETTC., JSC tập trung vào nhiều nhóm giải pháp chuyên dụng:</p><ul><li><p><strong>Intelligent Surveillance &amp; CCTV</strong> – hệ thống camera và giám sát thông minh.</p></li><li><p><strong>Audio &amp; Video Technology</strong> – giải pháp ghi âm, xử lý, tổng hợp và phân tích dữ liệu âm thanh, hình ảnh.</p></li><li><p><strong>Biometrics &amp; Identification</strong> – công nghệ sinh trắc học, nhận dạng khuôn mặt và nhận dạng đa phương thức.</p></li><li><p><strong>Forensic Technology</strong> – thiết bị và giải pháp phục vụ giám định kỹ thuật, xử lý tài liệu và hình ảnh chuyên dụng.</p></li><li><p><strong>Security Screening &amp; Detection</strong> – hệ thống soi chiếu, phát hiện và tìm kiếm chất nổ, ma túy, hóa chất và các vật liệu nguy hiểm.</p></li><li><p><strong>RF &amp; Electronic Security</strong> – các giải pháp phát hiện, giám sát và bảo đảm an ninh sử dụng công nghệ vô tuyến.</p></li><li><p><strong>Radiation &amp; Hazardous Material Detection</strong> – thiết bị phát hiện phóng xạ và các tác nhân nguy hiểm.</p></li><li><p><strong>Specialized Operational Equipment</strong> – các thiết bị nghiệp vụ chuyên dụng và công nghệ phục vụ an ninh – quốc phòng.</p></li></ul><h3>Công nghệ quốc tế – Năng lực triển khai tại Việt Nam</h3><p>Thông qua mạng lưới đối tác quốc tế, VIETTC., JSC có khả năng tiếp cận nhiều công nghệ chuyên ngành từ các thị trường phát triển. Hồ sơ năng lực ghi nhận hệ thống đối tác và thương hiệu trong các lĩnh vực <strong>quét dựng 3D, camera an ninh, RF, kính hiển vi, soi chiếu, sinh trắc học, nhận dạng khuôn mặt, xử lý âm thanh – hình ảnh, phát hiện phóng xạ và thiết bị phát hiện chất nổ</strong>.</p><p>Điểm khác biệt của VIETTC., JSC nằm ở khả năng <strong>chuyển hóa công nghệ thành giải pháp thực tế</strong>. Từ khảo sát nhu cầu, tư vấn công nghệ, lựa chọn thiết bị, tích hợp hệ thống, chuyển giao công nghệ, lắp đặt và đào tạo đến bảo hành, bảo trì và hỗ trợ kỹ thuật, chúng tôi hướng tới một quy trình triển khai đồng bộ và xuyên suốt. Đội ngũ kỹ thuật của công ty có kinh nghiệm trực tiếp làm việc với chuyên gia nước ngoài, lắp đặt, vận hành, đào tạo và chuyển giao lại công nghệ cho khách hàng trong nước.</p>','string','2026-09-04 19:25:13','2026-09-04 20:02:49'),(55,'technology_content_en','<p></p><p><img src=\"http://127.0.0.1:8000/storage/settings/technology/8k8X0ozjT5WmAZ1xFZt9xeGxVApUUQ91OWZ8EUsP.png\" data-id=\"settings/technology/8k8X0ozjT5WmAZ1xFZt9xeGxVApUUQ91OWZ8EUsP.png\"></p><p></p><p>At <strong>VIETTC., JSC</strong>, technology goes beyond the equipment we provide. It represents our capabilities in <strong>research, system integration, technology transfer, and technology application</strong> to address specialized requirements across the <strong>security, defense, and high-tech industries</strong>.</p><p>With more than <strong>20 years of experience</strong>, VIETTC., JSC has established a strong network of cooperation with <strong>research institutes, experts, manufacturers, and international technology groups</strong>, enabling us to continuously access advanced technologies and transform them into practical solutions for customers in Vietnam.</p><h3>COMPREHENSIVE TECHNOLOGY CAPABILITIES</h3><p>VIETTC., JSC brings together a team of technical specialists and experts with strong backgrounds in <strong>telecommunications, information technology, and specialized engineering</strong>. Our Technical &amp; Solutions Division is responsible for researching and evaluating technologies, working closely with domestic and international partners to select, transfer, integrate, and develop solutions that meet specific operational requirements.</p><p>Our <strong>research and product development capabilities</strong> also enable VIETTC., JSC to actively participate in the development and manufacturing of specialized equipment for our projects, going beyond the role of a conventional equipment supplier.</p><h3>TECHNOLOGY AREAS</h3><p>Our technology capabilities cover a broad range of specialized solutions, including:</p><ul><li><p><strong>Intelligent Surveillance &amp; CCTV</strong> – intelligent camera and surveillance systems.</p></li><li><p><strong>Audio &amp; Video Technology</strong> – solutions for audio recording, processing, aggregation, and analysis of audio and visual data.</p></li><li><p><strong>Biometrics &amp; Identification</strong> – biometric technologies, facial recognition, and multimodal identification solutions.</p></li><li><p><strong>Forensic Technology</strong> – specialized equipment and solutions for forensic examination, document processing, and image analysis.</p></li><li><p><strong>Security Screening &amp; Detection</strong> – screening, detection, and search systems for explosives, narcotics, chemicals, and hazardous materials.</p></li><li><p><strong>RF &amp; Electronic Security</strong> – radio-frequency technologies for detection, monitoring, and security applications.</p></li><li><p><strong>Radiation &amp; Hazardous Material Detection</strong> – technologies for detecting radiation and other hazardous materials.</p></li><li><p><strong>Specialized Operational Equipment</strong> – specialized equipment and technologies supporting security and defense operations.</p></li></ul><h3>GLOBAL TECHNOLOGY – LOCAL IMPLEMENTATION</h3><p>Through our international technology network, VIETTC., JSC gains access to advanced technologies from leading markets around the world. Our technology ecosystem encompasses <strong>3D scanning and reconstruction, security surveillance, RF technology, microscopy, security screening, biometrics, facial recognition, audio and video processing, radiation detection, and explosive detection</strong>.</p><p>Our key strength lies in our ability to <strong>transform advanced technology into practical, deployable solutions</strong>. From <strong>requirements assessment, technology consulting, and equipment selection to system integration, technology transfer, installation, training, maintenance, and technical support</strong>, VIETTC., JSC provides an integrated approach throughout the entire solution lifecycle.</p><p>Our technical team works directly with international specialists and technology partners in <strong>installation, system commissioning, operation, training, and technology transfer</strong>, ensuring that advanced technologies are effectively implemented and operated by customers in Vietnam.</p><blockquote><p><strong>From Global Technology to Local Solutions.</strong><br><strong>From Advanced Equipment to Real-World Capabilities.</strong><br><strong>VIETTC., JSC — Your Trusted Technology Partner.</strong></p></blockquote>','string','2026-09-04 19:25:13','2026-09-04 20:02:49'),(56,'about_image_path','settings/about/01M1QSX7D39291AE8Q4ADE3JZK.png','string','2026-09-04 19:27:53','2026-09-04 20:31:01');
